    # -- TTS no longer leaves a visible duplicate message (post-1.8.2) -
    async def test_tts_trigger_message_gets_cleaned_up(self):
        db.set_setting("tts_enabled", "1")
        try:
            sink = []
            update = FakeUpdate(333333, "irrelevant", sink)
            await bot._maybe_speak(update, "The goblin attacks!", None)
            self.assertEqual(sink, ["/tts The goblin attacks!"])
            self.assertFalse(update.effective_chat.last_sent_message.deleted)
            # Poll instead of a single fixed sleep -- under heavy system
            # load (this box regularly sees asyncio scheduling delays of
            # 10+ seconds while Ollama holds the CPU) a flat sleep
            # occasionally loses the race against the cleanup task's own
            # internal sleep, flaking a test that isn't actually broken.
            # TTS_TRIGGER_DELETE_DELAY_SECONDS is 20s (bumped 2026-07-16,
            # real live feedback that 2s was too fast to actually tap the
            # message) -- poll well past that for real headroom.
            asyncio = __import__("asyncio")
            for _ in range(70):
                if update.effective_chat.last_sent_message.deleted:
                    break
                await asyncio.sleep(0.5)
            self.assertTrue(update.effective_chat.last_sent_message.deleted)
        finally:
            db.set_setting("tts_enabled", "0")

    # -- The Unmoored Isle is actually reachable (post-1.9.2) ---------
    async def test_unmoored_isle_reachable_with_shard_blocked_without(self):
        """
        Found while mapping the location graph for the reverse
        playthrough: The Unmoored Isle (real quest, real interactables,
        a requires_item gate) had no connection from ANYWHERE in the
        whole campaign -- completely unreachable dead content. Fixed
        by adding ascends_to on The First City.

        Real chapter-order audit (2026-09-09, per Coffee: "dont let
        players skip chapters... has to be played in order"): holding
        shard_of_dim_light alone used to be enough -- but that item is
        Chapter 2's own first-quest reward, so a player who'd only
        finished Chapter 2 could skip all ten of Chapter 3's quests
        straight into Chapter 4. Now also requires
        the_original_spires_reckoning (Chapter 3's real finale quest)
        completed, via a real story_gates entry (requires_completed_
        quest) on the_first_city -- checked by the same _check_story_
        gate every other chapter boundary already uses.
        """
        user_id = 888888
        make_basic_character(user_id, "Roamer", current_location="the_first_city")
        db.update_character(user_id, -999, level=10)

        sink = []
        await bot.adventure_master_handler(
            FakeUpdate(user_id, "Ascend to the Unmoored Isle", sink), DummyContext())
        character = db.get_character(user_id, -999)
        self.assertEqual(character["current_location"], "the_first_city")  # blocked, no shard

        db.add_item(user_id, -999, "shard_of_dim_light", 1)
        sink.clear()
        await bot.adventure_master_handler(
            FakeUpdate(user_id, "Ascend to the Unmoored Isle", sink), DummyContext())
        character = db.get_character(user_id, -999)
        self.assertEqual(
            character["current_location"], "the_first_city",
            "must still be blocked -- Chapter 3 (the_original_spires_reckoning) isn't done yet",
        )

        db.update_character(user_id, -999, completed_quests=["the_original_spires_reckoning"])
        sink.clear()
        await bot.adventure_master_handler(
            FakeUpdate(user_id, "Ascend to the Unmoored Isle", sink), DummyContext())
        character = db.get_character(user_id, -999)
        self.assertEqual(character["current_location"], "the_unmoored_isle")

    async def test_first_city_hides_the_ascend_hint_until_the_shard_is_actually_held(self):
        """
        Real live report (2026-08-26, Coffee: "in the first city you
        have a location showing (sky) but the location is for a evolved
        3 character... please not even show it until it is time for the
        player to go there, that way they dont get stuck by travelling
        then not able to get back to the ground layer"). The Unmoored
        Isle has no path back down to the_first_city in its own
        "directions" (only deeper sky content past it) -- so a player
        who saw and followed "You could ascend to: The Unmoored Isle"
        before actually holding shard_of_dim_light could genuinely
        strand themselves the moment they somehow got up there anyway.
        _location_extra_detail's ascend/descend lines now check the
        same real gates _do_move already enforces before showing at
        all.
        """
        from unittest.mock import patch

        async def no_real_image_call(*args, **kwargs):
            return False

        class FakeResponse:
            def raise_for_status(self):
                pass

            def json(self):
                return {"response": "Something old and warm hums beneath the spire."}

        user_id = 888889
        make_basic_character(user_id, "PrematureRoamer", current_location="the_first_city")
        db.update_character(user_id, -999, level=10)
        db.add_item(user_id, -999, "torch", 1)  # so _do_look doesn't short-circuit on darkness first

        sink = []
        # the_first_city has a quest board with no cached quests yet in a
        # fresh test DB -- get_or_generate_all_board_quests lazily
        # generates one via a real Ollama call unrelated to the bug this
        # test targets, same reasoning as this file's other _do_look
        # tests that mock both real network calls _do_look can trigger.
        with patch("bot._send_generated_image", side_effect=no_real_image_call), \
             patch("ai.dm_agent.requests.post", return_value=FakeResponse()):
            await bot._do_look(FakeUpdate(user_id, "look around", sink))
        reply = "\n".join(sink)
        self.assertNotIn("Unmoored Isle", reply, "shouldn't be hinted at before the shard is held")

        # Real chapter-order audit (2026-09-09): holding the shard alone
        # must still NOT show the hint -- Chapter 3's finale quest
        # (the_original_spires_reckoning) isn't done yet, and the hint
        # would otherwise invite a move _do_move now correctly refuses.
        db.add_item(user_id, -999, "shard_of_dim_light", 1)
        sink.clear()
        with patch("bot._send_generated_image", side_effect=no_real_image_call), \
             patch("ai.dm_agent.requests.post", return_value=FakeResponse()):
            await bot._do_look(FakeUpdate(user_id, "look around", sink))
        reply = "\n".join(sink)
        self.assertNotIn("Unmoored Isle", reply, "shouldn't be hinted at before Chapter 3 is actually done")

        db.update_character(user_id, -999, completed_quests=["the_original_spires_reckoning"])
        sink.clear()
        with patch("bot._send_generated_image", side_effect=no_real_image_call), \
             patch("ai.dm_agent.requests.post", return_value=FakeResponse()):
            await bot._do_look(FakeUpdate(user_id, "look around", sink))
        reply = "\n".join(sink)
        self.assertIn("You could ascend to: The Unmoored Isle", reply, reply)

    # -- The Unmoored Isle has a real final boss (post-1.10.0) --------
    def test_unmoored_isle_has_a_real_unfleeable_boss(self):
        """
        The First City and The Unmoored Isle (the campaign's two
        deepest locations) had zero monsters -- nothing to fight at
        the actual climax, despite the isle's own interactable text
        foreshadowing a confrontation. Structural checks only here
        (data correctness) -- the full live fight-to-completion path
        was verified live as far as system load allowed (reachability,
        accepting the quest while already present, and combat
        correctly engaging the boss all confirmed live); the final
        defeat->quest-complete link reuses the exact same generic
        _check_quest_completions_defeat_monster code already proven
        live for a different quest (Grask's) the same day.
        """
        monster = bot.CAMPAIGN["monsters"]["the_waiting_shape"]
        self.assertTrue(monster["is_boss"])
        self.assertGreater(monster["hp_max"], 21)  # tougher than goblin_boss

        location = bot.CAMPAIGN["locations"]["sky"]["the_unmoored_isle"]
        self.assertIn("the_waiting_shape", location.get("monsters", []))

        quest = bot.CAMPAIGN["quests"]["the_unmoored_isle_quest"]
        self.assertEqual(quest["trigger"]["type"], "defeat_monster")
        self.assertEqual(quest["trigger"]["monster"], "the_waiting_shape")

