    def test_suggested_level_shows_real_data_never_an_invented_number(self):
        """
        Real live request (2026-08-23, Coffee, screenshot of The
        Wayfarer's Circuit's offer): "can you please put the preferred
        or suggested level for these quest so the player knows?!"
        Grounded only in real campaign.json data -- an arc with a real
        required_level shows a real number, an unbanded arc (5-14, left
        at a 99 placeholder) shows a chapter position instead, a side
        quest resolves its REAL destination (not its shallow offer
        spot) via the location-to-chapter graph, and a Remnant gets no
        label at all (a deliberately separate, non-chapter-bound ladder).
        """
        arc1_quest_id = bot.CAMPAIGN["story_arcs"]["arc_1_discovery"]["quests"][0]
        arc1_quest = bot.CAMPAIGN["quests"][arc1_quest_id]
        self.assertEqual(bot._quest_suggested_level(arc1_quest_id, arc1_quest), "⭐ **Suggested Level:** 1+")

        arc9_quest_id = bot.CAMPAIGN["story_arcs"]["arc_9_whispering_wood"]["quests"][0]
        arc9_quest = bot.CAMPAIGN["quests"][arc9_quest_id]
        level_line = bot._quest_suggested_level(arc9_quest_id, arc9_quest)
        self.assertIn("Chapter 9", level_line)
        self.assertNotIn("Suggested Level", level_line)

        # The Wayfarer's Circuit: offered standing in whispering_wood (arc_1),
        # but its real objective is whispering_wood_sunken_den (arc_9 territory).
        wayfarers = bot.CAMPAIGN["quests"]["wayfarers_circuit"]
        level_line = bot._quest_suggested_level("wayfarers_circuit", wayfarers)
        self.assertIn("Chapter 9", level_line)

        remnant_id = "remnant_the_wrathflame_unbound"
        remnant_quest = bot.CAMPAIGN["quests"][remnant_id]
        self.assertEqual(bot._quest_suggested_level(remnant_id, remnant_quest), "")

    def test_early_onramp_quest_shows_its_own_prerequisites_level_not_its_far_off_zones(self):
        """
        Real live bug (2026-08-27, Coffee, dev-bridge screenshot: "Is
        this the proper kess quest?! Why is it showing a suggested
        level of 75?! I think there's something wrong with the quest").
        borins_blackthorn_warning is a deliberate early on-ramp --
        offerable right after first_city_arrival (arc_3, real
        required_level 10) -- whose own trigger is just reaching
        greymoor_downs' entrance, one of the "meet the weak stuff at
        the front door" zone entrances that deliberately sits BELOW
        that zone's real difficulty band (75-99). The old geographic
        fallback showed the zone's own far-later band instead of this
        quest's real, explicit, author-placed gate
        (requires_completed_quest), which is the actual signal that
        matters for "should I accept this now."
        """
        quest = bot.CAMPAIGN["quests"]["borins_blackthorn_warning"]
        self.assertEqual(bot._quest_suggested_level("borins_blackthorn_warning", quest), "⭐ **Suggested Level:** 10+")

        # kess_first_reckoning itself is IN arc_8, but as a dynamic-
        # scaling NPC-dict boss quest it now shows Kess's own real,
        # far-less-alarming NPC level (23+) instead of the arc's static
        # 75+ band (2026-08-28, per Coffee: "use the actual suggest lv
        # for the quests" -- the 75+ label was scaring a real level-24
        # party away from a fight that actually scales to match them).
        # See test_suggested_level_notes_dynamic_scaling_only_for_a_
        # real_npc_dict_boss below for the dedicated test of this.
        kess_quest = bot.CAMPAIGN["quests"]["kess_first_reckoning"]
        self.assertEqual(
            bot._quest_suggested_level("kess_first_reckoning", kess_quest),
            "⭐ **Suggested Level:** 23+ (this fight scales to your own party's level)",
        )

        # The Wayfarer's Circuit has no requires_completed_quest of its
        # own -- must be completely unaffected by this fix, still
        # falling through to the geographic destination-based inference.
        wayfarers = bot.CAMPAIGN["quests"]["wayfarers_circuit"]
        self.assertIsNone(wayfarers.get("requires_completed_quest"))
        level_line = bot._quest_suggested_level("wayfarers_circuit", wayfarers)
        self.assertIn("Chapter 9", level_line)

    def test_suggested_level_notes_dynamic_scaling_only_for_a_real_npc_dict_boss(self):
        """
        Real live follow-up (2026-08-28, Coffee: "add that note check
        the level suggestion for future users" -- re: kess_first_
        reckoning's real "Suggested Level: 75+" alarming a much-lower-
        level party into thinking it was a hard wall, when Kess's own
        stats actually dynamically rescale to the party). Confirmed by
        audit: exactly two quests target a real NPC-dict boss
        (kess_the_bandit/kess_the_unbound) -- every other defeat_monster
        quest targets a static "monsters"-dict template with a fixed
        final stat block, so those must NOT get this note (it wouldn't
        be true for them).
        """
        kess_quest = bot.CAMPAIGN["quests"]["kess_first_reckoning"]
        kess_level_line = bot._quest_suggested_level("kess_first_reckoning", kess_quest)
        self.assertIn("scales to your own party's level", kess_level_line)
        # Real live follow-up (2026-08-28, "use the actual suggest lv
        # for the quests"): Kess's own real NPC level (23), not arc_8's
        # static 75+ band, which was never actually true for her.
        self.assertIn("Suggested Level:** 23+", kess_level_line)

        unbound_quest = bot.CAMPAIGN["quests"]["kess_the_unbound_reckoning"]
        unbound_level_line = bot._quest_suggested_level("kess_the_unbound_reckoning", unbound_quest)
        self.assertIn("scales to your own party's level", unbound_level_line)
        self.assertIn("Suggested Level:** 25+", unbound_level_line)

        # A real static-monster defeat_monster quest (goblin_boss lives
        # in the "monsters" dict, not "npcs") must NOT get the note.
        static_quest = bot.CAMPAIGN["quests"]["clear_the_warrens"]
        self.assertEqual(static_quest["trigger"]["type"], "defeat_monster")
        self.assertNotIn("scales to your own party's level", bot._quest_suggested_level("clear_the_warrens", static_quest))

        # A non-defeat_monster quest (reach_location) must also be unaffected.
        self.assertNotIn(
            "scales to your own party's level",
            bot._quest_suggested_level("borins_blackthorn_warning", bot.CAMPAIGN["quests"]["borins_blackthorn_warning"]),
        )

    def test_greymoor_downs_quests_now_show_a_real_suggested_level_not_just_a_chapter(self):
        """
        Real live report (2026-08-27, Coffee: "quests that would pop
        up, but no Avg lv was posted beside them so it is unclear to
        the player when they shud do them... Maybe post an avg lvl
        needed to complete the quest?"). Chapters 5-8 already have a
        real, Coffee-confirmed level-band model (2026-08-19,
        v1.27.263-266: goblin_warrens 40-55, sunken_root_caverns 50-65,
        stonearch_gorge 60-75, greymoor_downs 75-99) that was never
        wired into required_level -- it stayed at the 99 placeholder,
        so these arcs fell back to a bare "Chapter N" label with no
        real level number, same gap arcs 9-14 still have (those remain
        unbanded/untouched -- explicitly future work).
        """
        for arc_id, expected_level, quest_override in (
            ("arc_5_goblin_warrens", 40, None),
            ("arc_6_sunken_root_caverns", 50, None),
            ("arc_7_stonearch_gorge", 60, None),
            # arc_8's own literal first quest is now borins_blackthorn_
            # warning (2026-08-28, added as a real arc member to fix its
            # arc-opening cutscene/order gating) -- a deliberate early
            # on-ramp that correctly shows ITS OWN lower prereq-derived
            # level (10+, see test_early_onramp_quest_shows_its_own_
            # prerequisites_level_not_its_far_off_zones), not the arc's
            # band. watchtowers_stalker (arc_8's first real wolf quest,
            # no prereq of its own) is the representative quest for
            # arc_8's own confirmed band here instead.
            ("arc_8_greymoor_downs", 75, "watchtowers_stalker"),
        ):
            quest_id = quest_override or bot.CAMPAIGN["story_arcs"][arc_id]["quests"][0]
            quest = bot.CAMPAIGN["quests"][quest_id]
            self.assertEqual(
                bot._quest_suggested_level(quest_id, quest),
                f"⭐ **Suggested Level:** {expected_level}+",
                f"{arc_id} should show its real confirmed band floor, not a bare chapter label",
            )

        # arc_9 (still unbanded, deliberately untouched) must keep its
        # existing "Chapter N" fallback -- confirms this fix didn't
        # accidentally widen past arc_8.
        arc9_quest_id = bot.CAMPAIGN["story_arcs"]["arc_9_whispering_wood"]["quests"][0]
        arc9_quest = bot.CAMPAIGN["quests"][arc9_quest_id]
        level_line = bot._quest_suggested_level(arc9_quest_id, arc9_quest)
        self.assertIn("Chapter 9", level_line)
        self.assertNotIn("Suggested Level", level_line)

    # -- Spell progression actually reaches every level the unlock table
    #    promises, up to character level 9 (v1.10.3) ---------------------
    def test_every_class_has_real_spells_at_every_promised_tier(self):
        """
        SPELL_LEVEL_UNLOCK_CHAR_LEVEL promised 4th/5th-level spells at
        character levels 7/9, but no spell of either level existed in
        SPELLS at all -- full casters got nothing new from level 7
        onward. Added real 4th/5th-level spells and wired them into
        every full caster's CLASS_SPELL_LISTS; paladin/ranger (half-
        casters) are allowed to cap out early, same as they already did
        for 2nd/3rd level before this fix.
        """
        full_casters = ["wizard", "sorcerer", "cleric", "druid", "bard", "warlock"]
        for cls in full_casters:
            highest_known = max(
                spells.SPELLS[s]["level"] for s in spells.spells_unlocked_at_level(cls, 9)
            )
            self.assertEqual(highest_known, 5, f"{cls} caps below the promised 5th-level tier")

    def test_no_orphaned_spells_unreachable_by_any_class(self):
        referenced = set()
        for cantrips in spells.CLASS_CANTRIPS.values():
            referenced.update(cantrips)
        for spell_list in spells.CLASS_SPELL_LISTS.values():
            referenced.update(spell_list)
        # Arcane Circle exclusive spells (2026-07-25) are deliberately NOT
        # in any CLASS_SPELL_LISTS entry -- spells.py's own comment above
        # starfall_lance/voidcall says so -- reachable only via guild
        # membership + bot.py's _do_learn_guild_spell. This test predates
        # that real reachability path, same stale-assumption shape as the
        # 3 tests fixed in 822e728.
        referenced.update(sid for sid, _min_rebirth in guilds.ARCANE_CIRCLE_EXCLUSIVE_SPELLS)
        # Scroll-only spells (2026-09-09, same stale-assumption shape
        # again -- found via a real, confirmed dev-bridge-adjacent
        # investigation, not just re-run and ignored): a real find/buy/
        # loot scroll is just as real a reachability path as a class
        # list or guild membership, and this must stay computed live
        # from items.py rather than a second hardcoded id list that can
        # drift out of sync with future scrolls the way this exact test
        # already has twice.
        for item in items_module.ITEMS.values():
            if item.get("type") == "scroll" and item.get("spell"):
                referenced.add(item["spell"])
        orphaned = set(spells.SPELLS.keys()) - referenced
        self.assertEqual(orphaned, set(), f"unreachable by any class: {orphaned}")

    # -- Cleric's Divine Domain (Life Domain fixed-default) was flavor
    #    text only; Disciple of Life is now a real heal bonus (v1.10.3) --
    def test_cleric_disciple_of_life_adds_bonus_healing(self):
        cleric = {"char_class": "Cleric", "name": "Test Cleric"}
        target = {"name": "Ally", "hp_current": 1, "hp_max": 100}
        result = spells.resolve_heal_spell("cure_wounds", cleric, target)
        # cure_wounds is heal_dice "1d8+2" (min 3) + Disciple of Life's
        # 2 + spell level (1) = +3 -- minimum possible total is 6.
        self.assertGreaterEqual(result["healing_done"], 6)

    def test_non_cleric_gets_no_disciple_of_life_bonus(self):
        wizard = {"char_class": "Wizard", "name": "Test Wizard"}
        target = {"name": "Ally", "hp_current": 1, "hp_max": 100}
        result = spells.resolve_heal_spell("cure_wounds", wizard, target)
        self.assertLessEqual(result["healing_done"], 11)  # 1d8+2 max, no bonus

    def test_faith_circle_heal_bonus_scales_with_growth_tier(self):
        """
        "Fill all gaps" pass (2026-09-10): the old flat +3 heal bonus
        never grew past day-one membership -- now a real level/
        evolution-tiered +3/+5/+8/+12/+15. Mocks spells.guild_growth_
        tier_bonus directly (both members otherwise identical, level 1,
        rebirth 0) to isolate this one addend from the SEPARATE, real
        power_scale_ratio(level, rebirth_count) multiplier every heal
        already goes through -- varying level/rebirth here would
        confound both effects together. The tier table's own real
        level/rebirth thresholds are covered by
        test_guild_growth_tier_bonus_table_scales_correctly instead.
        """
        from unittest.mock import patch
        target_template = {"name": "Ally", "hp_current": 1, "hp_max": 1000}
        base_member = {"char_class": "Fighter", "name": "BaseMember", "guild": "faith_circle"}
        higher_tier_member = {"char_class": "Fighter", "name": "HigherTierMember", "guild": "faith_circle"}
        with patch("rules.dice.random.randint", return_value=4), \
             patch("spells.guild_growth_tier_bonus", return_value=3):
            base_result = spells.resolve_heal_spell("cure_wounds", base_member, dict(target_template))
        with patch("rules.dice.random.randint", return_value=4), \
             patch("spells.guild_growth_tier_bonus", return_value=15):
            higher_tier_result = spells.resolve_heal_spell("cure_wounds", higher_tier_member, dict(target_template))
        # Non-Cleric (no Disciple of Life) + forced die value 4 + no
        # power_scale_ratio growth (level 1, rebirth 0, identical for
        # both): base heal is identical (1d8+2 -> 6) for both, so the
        # delta isolates the mocked guild bonus itself: 15 - 3 = 12.
        self.assertEqual(higher_tier_result["healing_done"] - base_result["healing_done"], 12)

    # -- Guild membership benefits were data-only; bonus_spell_scroll and
    #    bonus_damage_vs_undead had nothing checking them (v1.10.4) ------
    def test_silver_wardens_bonus_damage_vs_undead(self):
        # AC 1 guarantees a hit on any roll except a natural 1 (5E
        # auto-miss regardless of AC) or natural 20 (crit, which would
        # double the weapon die and complicate the exact-damage check) --
        # retry until a plain hit so those ~10% of rolls don't make this
        # test flaky.
        attacker = {
            "name": "Warden", "dexterity": 14, "strength": 16, "armor_class": 15,
            "hp_current": 20, "hp_max": 20, "char_class": "Fighter", "guild": "silver_wardens",
        }
        weapon = {"ability": "strength", "damage_dice": "1d1", "damage_bonus": 0}
        for _ in range(20):
            defender = {
                "name": "Shadow Wisp", "dexterity": 18, "armor_class": 1,
                "hp_current": 100, "hp_max": 100, "monster_key": "shadow_wisp",
            }
            result = resolve_attack(attacker, defender, weapon)
            if result["hit"] and not result["critical_hit"]:
                self.assertEqual(result["damage_dealt"], 3)  # 1 (die) + 2 (warden bonus)
                return
        self.fail("no plain (non-crit) hit landed in 20 tries at AC 1 -- suspiciously unlucky or broken")

