    async def test_trade_add_names_real_candidates_when_genuinely_ambiguous(self):
        """
        Real live bug (2026-08-27, Coffee dev-bridge: "I am trying to
        add items to the trade and it's not letting me" -- "Add 5
        scrolls of spirits to the trade"). Not actually a bug in the
        matcher: Elduinn genuinely owns BOTH Scroll of the Lesser
        Spirit and Scroll of the Spirit, which share "Spirit" as their
        real head noun, so "scrolls of spirits" is a real, deliberate
        ambiguity -- but the old generic "Add what to the trade,
        exactly?" message gave no hint that a real choice was needed,
        indistinguishable from "nothing matched at all." Now names the
        real candidates so the player knows to be specific.
        """
        import sessions
        sessions.end_session(-999)
        a_id, b_id = 951009, 951010
        make_basic_character(a_id, "SpiritTraderA", current_location="crossroads_tavern")
        make_basic_character(b_id, "SpiritTraderB", current_location="crossroads_tavern")
        db.add_item(a_id, -999, "scroll_summon_spirit", 13)
        db.add_item(a_id, -999, "scroll_summon_spirit_ii", 10)

        sink = []
        await bot._do_trade_request(FakeUpdate(a_id, "trade with SpiritTraderB", sink), "trade with SpiritTraderB")
        sink.clear()
        await bot._do_trade_add(
            FakeUpdate(a_id, "Add 5 scrolls of spirits to the trade", sink),
            "Add 5 scrolls of spirits to the trade",
        )
        reply = sink[-1]
        self.assertIn("which one", reply.lower())
        self.assertIn("Scroll of the Lesser Spirit", reply)
        self.assertIn("Scroll of the Spirit", reply)
        # Neither scroll should have actually moved -- a genuinely
        # ambiguous phrase must never guess.
        after = db.get_character(a_id, -999)
        self.assertEqual(after["inventory"].get("scroll_summon_spirit", 0), 13)
        self.assertEqual(after["inventory"].get("scroll_summon_spirit_ii", 0), 10)

    async def test_trade_add_resolves_a_pluralized_exact_multiword_name(self):
        """
        Real live bug (2026-08-27, found via topic-activity monitoring
        right after shipping the ambiguity-naming fix above): "Add 10
        scrolls of the spirit to the trade" -- the exact real name of
        Scroll of the Spirit, just pluralized -- failed to resolve at
        all, even though the SINGULAR "Scroll of the Spirit" worked.
        English pluralizes a multi-word item name at its FIRST word
        ("Scroll" -> "Scrolls"), not its last, so the exact-name
        substring check never matched, and the phrase fell through to
        the weaker head-word fallback -- ambiguous here since Scroll of
        the Lesser Spirit shares the same head noun "spirit", wrongly
        landing on "which one?" for a genuinely unambiguous plural.
        """
        import sessions
        sessions.end_session(-999)
        a_id, b_id = 951017, 951018
        make_basic_character(a_id, "PluralTraderA", current_location="crossroads_tavern")
        make_basic_character(b_id, "PluralTraderB", current_location="crossroads_tavern")
        db.add_item(a_id, -999, "scroll_summon_spirit", 13)
        db.add_item(a_id, -999, "scroll_summon_spirit_ii", 10)

        sink = []
        await bot._do_trade_request(FakeUpdate(a_id, "trade with PluralTraderB", sink), "trade with PluralTraderB")
        sink.clear()
        await bot._do_trade_add(
            FakeUpdate(a_id, "Add 3 scrolls of the spirit to the trade", sink),
            "Add 3 scrolls of the spirit to the trade",
        )
        self.assertTrue(any("Added 3x Scroll of the Spirit" in m for m in sink), sink)
        after = db.get_character(a_id, -999)
        self.assertEqual(after["inventory"].get("scroll_summon_spirit_ii", 0), 7)
        self.assertEqual(after["inventory"].get("scroll_summon_spirit", 0), 13, "the OTHER spirit scroll must be untouched")

    async def test_trade_offer_change_resets_the_other_sides_accept_flag(self):
        import sessions
        sessions.end_session(-999)
        a_id, b_id = 951007, 951008
        make_basic_character(a_id, "ResetA", current_location="crossroads_tavern")
        make_basic_character(b_id, "ResetB", current_location="crossroads_tavern")
        db.add_item(a_id, -999, "healing_potion", 2)

        sink = []
        await bot._do_trade_request(FakeUpdate(a_id, "trade with ResetB", sink), "trade with ResetB")
        # Only B accepts here -- if BOTH accepted, the trade would
        # immediately finalize and clear (design decision: mutual
        # accept auto-executes), leaving nothing left to test the
        # reset-on-change behavior against.
        await bot._do_trade_accept(FakeUpdate(b_id, "accept the trade", sink))
        record = bot._find_trade_for_user(-999, a_id)
        self.assertTrue(record["party_b"]["accepted"])

        await bot._do_trade_add(FakeUpdate(a_id, "add 1 healing potion to the trade", sink), "add 1 healing potion to the trade")
        record = bot._find_trade_for_user(-999, a_id)
        self.assertFalse(record["party_a"]["accepted"], "the side that changed its own offer must not be marked accepted")
        self.assertFalse(record["party_b"]["accepted"], "the OTHER side must also un-accept -- it agreed to a now-stale offer")

    async def test_trade_executes_atomically_on_mutual_accept_and_swaps_real_inventory_and_gold(self):
        import sessions
        sessions.end_session(-999)
        a_id, b_id = 951009, 951010
        make_basic_character(a_id, "SwapA", current_location="crossroads_tavern")
        make_basic_character(b_id, "SwapB", current_location="whispering_wood")
        db.add_item(a_id, -999, "healing_potion", 1)
        db.add_item(b_id, -999, "torch", 1)
        db.update_character(a_id, -999, gold=100)
        db.update_character(b_id, -999, gold=50)

        sink = []
        await bot._do_trade_request(FakeUpdate(a_id, "trade with SwapB", sink), "trade with SwapB")
        await bot._do_trade_add(FakeUpdate(a_id, "add 1 healing potion to the trade", sink), "add 1 healing potion to the trade")
        await bot._do_trade_add(FakeUpdate(a_id, "add 20 gold to the trade", sink), "add 20 gold to the trade")
        await bot._do_trade_add(FakeUpdate(b_id, "add 1 torch to the trade", sink), "add 1 torch to the trade")
        await bot._do_trade_accept(FakeUpdate(a_id, "accept the trade", sink))
        await bot._do_trade_accept(FakeUpdate(b_id, "accept the trade", sink))

        final_a = db.get_character(a_id, -999)
