    def test_support_spell_catalog_grounds_check_bonus_cantrips_real_mechanic(self):
        """
        Real live bug (2026-08-11, dev-topic report): "What does mage
        hand do?" got back "Mage Hand lets you cast spells without mana
        cost" -- a pure hallucination. Root cause: _spells_catalog_text
        only ever passed the model the bare word "buff" for cantrips like
        Mage Hand, with no real description of what that actually means
        in this game (a +2 bonus to the caster's own next skill check,
        per bot.py's _do_cast_spell), so the model filled the gap from
        general tabletop-RPG knowledge instead. The catalog text itself must name
        the real mechanic for all four cantrips that share it, and must
        not just say the bare word "buff" for them anymore.
        """
        from ai.support_agent import _spells_catalog_text
        catalog = _spells_catalog_text()
        for spell_name in ("Mage Hand", "Guidance", "Thaumaturgy", "Prestidigitation"):
            self.assertIn(spell_name, catalog)
        self.assertIn("+2 bonus to your own next skill/ability check", catalog)
        # Every mention of these four cantrips must carry the real
        # mechanic, never the bare unexplained "buff" tag alone.
        for line in catalog.splitlines():
            if "Mage Hand" in line:
                self.assertNotIn("(cantrip, buff)", line)
                self.assertIn("+2 bonus", line)

    # -- Real live bug (2026-07-16): this model has a documented bias
    #    toward guessing "pass_turn" for phrasing it doesn't recognize --
    #    "I'll take a mug, ale!!! how are you doing old buddy?" (ordinary
    #    tavern small talk, no active turn to pass) came back from the
    #    RAW MODEL as pass_turn, and since _keyword_fallback correctly
    #    says "chat" for it (no pass-turn phrase present), the model's
    #    ungrounded guess was trusted instead of the deterministic
    #    fallback, producing a confusing "There's no active turn to pass
    #    right now" reply to ordinary chatter. Mirrors the pre-existing
    #    start_combat guard's same defensive shape. -------------------
    def test_model_guessing_pass_turn_is_never_trusted_over_keyword_fallback(self):
        from unittest.mock import patch
        import ai.intent_parser as intent_parser_module

        class FakeResponse:
            def raise_for_status(self):
                pass

            def json(self):
                return {"response": '{"action": "pass_turn"}'}

        with patch("ai.intent_parser.requests.post", return_value=FakeResponse()):
            result = intent_parser_module.parse_intent(
                "I'll take a mug, ale!!! how are you doing old buddy?", []
            )
        self.assertEqual(result["action"], "chat")

    def test_model_guessing_attack_for_a_bare_emoji_is_never_trusted(self):
        """
        Real live bug (2026-08-11, live-confirmed by Coffee): sent "\U0001F608"
        (devil emoji) as banter/heckling aimed at a boss mid-fight, not a
        real combat command -- the model classified it as "attack" anyway,
        and the game actually spent a real combat turn attacking. Same
        defensive pattern as the pass_turn/start_combat guards: a message
        with no real letters at all has no verb for the model to have
        genuinely understood, so "attack" -- a stateful action with a
        real, hard-to-undo consequence when it fires wrongly -- is never
        trusted from the model alone for emoji/punctuation-only text.
        """
        from unittest.mock import patch
        import ai.intent_parser as intent_parser_module

        class FakeResponse:
            def raise_for_status(self):
                pass

            def json(self):
                return {"response": '{"action": "attack"}'}

        with patch("ai.intent_parser.requests.post", return_value=FakeResponse()):
            result = intent_parser_module.parse_intent("\U0001F608", [])
        self.assertEqual(result["action"], "chat")

    def test_model_guessing_flee_for_attack_flavor_text_is_never_trusted(self):
        """
        Real live bug (2026-08-11, topic-monitor report): "Take that you
        wretched" -- clearly aggressive attack-flavor combat banter, not
        an attempt to retreat -- got classified as "flee" anyway. Same
        defensive pattern as pass_turn: flee_words is already a
        deliberately broad, comprehensive list of every real way a
        player asks to run away, so if the keyword fallback found none
        of them, the model's own "flee" guess is never trusted alone --
        flee is a real, risky dice roll (can draw a real opportunity
        attack per CLAUDE.md), so a false positive derails the player's
        actual turn, not just a silent non-reply.
        """
        from unittest.mock import patch
        import ai.intent_parser as intent_parser_module

        class FakeResponse:
            def raise_for_status(self):
                pass

            def json(self):
                return {"response": '{"action": "flee"}'}

        with patch("ai.intent_parser.requests.post", return_value=FakeResponse()):
            result = intent_parser_module.parse_intent("Take that you wretched", [])
        self.assertEqual(result["action"], "chat")

        # No regression: a real flee phrase the keyword fallback already
        # knows about still works, whatever the model itself says.
        with patch("ai.intent_parser.requests.post", return_value=FakeResponse()):
            result = intent_parser_module.parse_intent("I try to flee from the goblin", [])
        self.assertEqual(result["action"], "flee")

    def test_model_guessing_dismantle_item_for_a_lost_confused_player_is_never_trusted(self):
        """
        Real live topic-activity signal (2026-08-27): a player typed
        "Which way" and then "I'm lost" -- clearly lost/confused
        navigation phrasing, not a request to break down gear -- and
        both got classified as dismantle_item. Same defensive pattern as
        pass_turn/flee/attack above: dismantle_item is a real, stateful,
        hard-to-undo action (permanently breaks down a real inventory
        item), so it's never trusted from the model alone unless the raw
        text actually contains one of its own real trigger words.
        """
        from unittest.mock import patch
        import ai.intent_parser as intent_parser_module

        class FakeResponse:
            def raise_for_status(self):
                pass

            def json(self):
                return {"response": '{"action": "dismantle_item"}'}

        with patch("ai.intent_parser.requests.post", return_value=FakeResponse()):
            result = intent_parser_module.parse_intent("Which way", [])
        self.assertEqual(result["action"], "chat")

        with patch("ai.intent_parser.requests.post", return_value=FakeResponse()):
            result = intent_parser_module.parse_intent("I'm lost", [])
        self.assertEqual(result["action"], "chat")

        # No regression: a real dismantle phrase the model happens to
        # agree with still works.
        with patch("ai.intent_parser.requests.post", return_value=FakeResponse()):
            result = intent_parser_module.parse_intent("Please dismantle my old sword", [])
        self.assertEqual(result["action"], "dismantle_item")

    def test_open_the_door_or_gate_routes_to_a_real_lockpick_attempt_not_examine(self):
        """
        Real live bug (2026-08-31, dev-bridge, Elduinn: "Open the door"
        at the Wrathflame Vault's own warded iron gate got "doesn't spot
        anything like that here" instead of actually attempting the
        lock). The generic "open X" -> examine catch-all had no
        awareness of lockables, so the single most natural phrase for a
        real locked door/gate never reached the real "pick the lock"
        dexterity check at all.
        """
        for phrase in ("Open the door", "open the gate", "try to open this door", "opening the warded gate"):
            result = _keyword_fallback(phrase, [])
            self.assertEqual(result["action"], "skill_check", f"{phrase!r} misclassified as {result['action']!r}")
            self.assertEqual(result["ability"], "dexterity")

        # No regression: an ordinary "open X" with no door/gate/lock word still examines.
        result = _keyword_fallback("open the chest", [])
        self.assertEqual(result["action"], "examine")

    def test_pull_the_lever_routes_to_a_real_lockpick_attempt_not_silence(self):
        """
        Real live bug (2026-09-01, dev-bridge screenshots: Sugar's
        "Pull the lever" and Charvenna's "Pull the thick root lever" --
        the exact room text says "A thick root lever is here, waiting
        to be pulled" -- got total silence, reported live as "why
        isn't this working, why is it so slow today"). Same exact gap
        class as the "open the door/gate" fix above, just never
        generalized to the lever kind: "pull" is the single most
        natural verb for a lever, but nothing ever routed it to
        skill_check, so it fell all the way through to the silent
        "chat" default.
        """
        for phrase in ("Pull the lever", "Pull the thick root lever", "pulling the switch", "I pull this lever"):
            result = _keyword_fallback(phrase, [])
            self.assertEqual(result["action"], "skill_check", f"{phrase!r} misclassified as {result['action']!r}")
            self.assertEqual(result["ability"], "dexterity")

    def test_asking_about_a_lockable_routes_to_examine_not_the_model(self):
        """
        Real live feature request (2026-08-31, dev-bridge, Elduinn: "I
        don't know if this area has a lever but if it doesn't, you
        should tell us"). A genuine QUESTION about a lockable is
        different from trying to open one -- routed to a real, honest
        examine (see _do_examine's own new lockable-aware fallback)
        instead of ever reaching the model at all.
        """
        for phrase in ("Look for a lever", "is there a lever here", "Do you see a lock", "any switch around"):
            result = _keyword_fallback(phrase, [])
            self.assertEqual(result["action"], "examine", f"{phrase!r} misclassified as {result['action']!r}")

        # No regression: the existing "look for hidden door" -> Perception-check phrasing is never shadowed.
        result = _keyword_fallback("look for hidden door", [])
        self.assertEqual(result["action"], "skill_check")
        self.assertEqual(result["ability"], "wisdom")

    async def test_examine_honestly_answers_whether_a_lockable_is_really_here(self):
        """The new lockable-aware examine fallback: real, distinct answers for a lever, a key-only gate, and no lockable at all -- never a roll, never an unlock, purely informative."""
        lever_loc = "wrathflame_vault_cinder_key_alcove"
