    def test_gathering_narration_is_grounded_in_the_real_tool_not_bare_hands(self):
        """
        Real live bug (2026-08-11, dev-topic report): "Gather iron ore"
        narrated Laurienna's "fingers clawed at the rough stone floor"
        despite her actually carrying a real Pickaxe -- _do_gather never
        passed narrate_skill_check's own grounded_fact parameter at all,
        so the model had zero real information about what implement was
        being used and invented bare hands instead. A character with the
        required tool must get a real fact naming it; a character
        without one (or a tool-free skill like herbalism) must not have
        a fact invented for them.
        """
        miner = {"name": "Laurienna", "inventory": {"pickaxe": 1}}
        fact = bot._gathering_tool_grounded_fact(miner, "mining")
        self.assertIsNotNone(fact)
        self.assertIn("Pickaxe", fact)
        self.assertIn("Laurienna", fact)

        no_tool_yet = {"name": "Laurienna", "inventory": {}}
        self.assertIsNone(bot._gathering_tool_grounded_fact(no_tool_yet, "mining"))

        herbalist = {"name": "Pip", "inventory": {}}
        self.assertIsNone(bot._gathering_tool_grounded_fact(herbalist, "herbalism"))

    async def test_do_gather_passes_the_real_tool_fact_to_narration(self):
        """
        End-to-end version of the fix above: a real "gather sulfur"
        call, with narrate_skill_check mocked to record its own call
        args, must be handed the real Pickaxe fact -- not silently
        drop it the way the pre-fix _do_gather call did.
        """
        from unittest.mock import patch

        user_id = 900541
        make_basic_character(user_id, "ToolCheck", current_location="sunken_root_caverns",
                              inventory={"pickaxe": 1})
        sink = []
        with patch("bot.roll_ability_check", return_value={
            "raw_roll": 20, "modifier": 0, "proficiency": 0, "total": 20,
        }), patch("bot.narrate_skill_check", return_value="Digs efficiently.") as mock_narrate:
            await bot._do_gather(FakeUpdate(user_id, "", sink), "gather sulfur")
        self.assertTrue(mock_narrate.called)
        call_args = mock_narrate.call_args.args
        self.assertIn("Pickaxe", call_args[-1])

    def test_skill_check_prompt_always_states_the_die_type_is_a_d20(self):
        """
        Real live bug (2026-09-01, dev-bridge screenshot): a failed
        gather check's narration read "The d12 whispers 4," despite the
        preamble already saying "the actual raw d20 number" in prose --
        the same model correctly said "d20" on its very next roll, a
        real success. The general instruction alone isn't a reliable
        enough guardrail for this model, so it's restated as its own
        isolated, hard "Known real fact" line -- present on every
        skill-check prompt, not just when a grounded_fact happens to be
        given.
        """
        import ai.dm_agent as dm_agent_module
        character = {"name": "Charvenna", "char_class": "Druid"}
        prompt = dm_agent_module._build_skill_check_prompt(
            character, "gather bitter-root herbs", "wisdom",
            {"raw_roll": 4, "total": 8, "dc": 13, "success": False},
        )
        self.assertIn("Known real fact: this is a d20 roll", prompt)
        self.assertIn("never a d12", prompt)

    def test_skill_check_prompt_tone_never_claims_the_opposite_of_the_real_outcome(self):
        """
        Real live bug (dev-bridge screenshot, 2026-09-12, Sugar): the
        SAME roll that got _format_skill_check_result's false "NATURAL 1
        -- Complete Failure!" banner (v1.27.588) also fed the narration
        prompt a hardcoded "This was a NATURAL 1 -- a humiliating,
        comedic total failure" tone instruction purely from raw_roll,
        ignoring the real `success: True` already sitting right there in
        mechanical_result -- which is exactly why her screenshot's
        narration read as an ambiguous near-failure ("resistance clawed
        back... a faint click lingered") despite a real, passing 22 vs
        DC 13. Unlike an attack roll (rules/dice.roll_attack bakes in
        the real 5E auto-hit/auto-miss rule, so critical framing there
        can never disagree with the real outcome), a skill check's
        natural 1/20 has no such rule -- success is pure `total >= dc`.
        The tone instruction must now agree with the real outcome.
        """
        import ai.dm_agent as dm_agent_module
        character = {"name": "Sugar", "char_class": "Rogue"}

        # Natural 1 that still succeeds -- must NOT call it a failure.
        prompt = dm_agent_module._build_skill_check_prompt(
            character, "pick the lock", "dexterity",
            {"raw_roll": 1, "total": 22, "dc": 13, "success": True},
        )
        self.assertNotIn("humiliating", prompt)
        self.assertNotIn("total failure", prompt)

        # Natural 20 that still fails -- must NOT call it a triumph.
        prompt2 = dm_agent_module._build_skill_check_prompt(
            character, "pick the lock", "dexterity",
            {"raw_roll": 20, "total": 20, "dc": 50, "success": False},
        )
        self.assertNotIn("legendary, spectacular critical success", prompt2)
        self.assertNotIn("triumphant", prompt2)

        # The real, consistent cases still get the big dramatic tone.
        prompt3 = dm_agent_module._build_skill_check_prompt(
            character, "pick the lock", "dexterity",
            {"raw_roll": 1, "total": 3, "dc": 13, "success": False},
        )
        self.assertIn("humiliating", prompt3)
        prompt4 = dm_agent_module._build_skill_check_prompt(
            character, "pick the lock", "dexterity",
            {"raw_roll": 20, "total": 25, "dc": 13, "success": True},
        )
        self.assertIn("legendary, spectacular critical success", prompt4)

    def test_puzzle_next_step_hint_prompt_requires_naming_the_real_location(self):
        """
        Real live report (2026-09-01, dev-bridge screenshot + caption,
        a player on "What Was Buried"): the puzzle-mode "What's Next...
        A Riddle" hint came back as pure mood text with zero actionable
        info -- "Within hushed depths where silence breathes, discern
        the whisper that stirs" -- no location, no lead, nothing a
        "lost" player could act on, even though the real quest's own
        Location fact (Watcher's Walk) was already in the prompt the
        whole time. The old preamble told the model it "may" evoke mood
        but never required it to actually surface the given Location by
        name, so the model treated it as skippable. Naming the location
        is not a spoiler -- only the puzzle's own answer is -- so the
        preamble now makes stating it mandatory.
        """
        import ai.dm_agent as dm_agent_module
        next_step = {
            "is_puzzle": True,
            "location_name": "Watcher's Walk",
            "clue": "The Watching Glyph at the end of Watcher's Walk poses a real riddle.",
        }
        prompt = dm_agent_module._build_next_step_hint_prompt(next_step)
        self.assertIn("Location: Watcher's Walk", prompt)
        self.assertIn("MUST plainly name the real Location", prompt)
        self.assertIn("NEVER state or imply the actual answer", prompt)

    def test_next_step_hint_fallback_stays_vague_for_a_puzzle(self):
        """
        Real live report (2026-09-02, Coffee, dev-bridge screenshot): a
        player saw the literal riddle question in the "What's Next... A
        Riddle" section. Root cause: the real Ollama call had failed
        that time, falling back to a template that included
        next_step["clue"] verbatim regardless of is_puzzle -- spilling
        the riddle question the real narration call is instructed to
        stay vague about, purely by accident of which path ran. The
        fallback must now stay just as vague as real narration is meant
        to be for a puzzle, and still show the real clue for the
        ordinary non-puzzle case (where that was always the design).
        """
        import ai.dm_agent as dm_agent_module
        from unittest.mock import patch
        with patch("ai.dm_agent.requests.post", side_effect=requests.RequestException("boom")):
            puzzle_hint = dm_agent_module.narrate_next_step_hint({
                "is_puzzle": True, "location_name": "The Sunken Archive",
                "clue": "The words carved at the recess's edge read: \"I speak without a mouth...\"",
            })
            self.assertNotIn("recess's edge", puzzle_hint)
            self.assertNotIn("mouth", puzzle_hint)

            quest_hint = dm_agent_module.narrate_next_step_hint({
                "is_puzzle": False, "location_name": "The Sunken Archive",
                "clue": "Borin needs a favor.",
            })
            self.assertIn("Borin needs a favor.", quest_hint)

    def test_next_step_hint_appends_location_and_quest_name_when_the_model_omits_them(self):
        """
        Real live report (2026-09-02, Coffee, dev-bridge screenshot): a
        real (non-fallback) narrated puzzle hint came back as "The
        enigmatic site whispers its truth through shadows" -- no
        location named anywhere, despite the prompt's own explicit
        "you MUST plainly name the real Location" instruction.
        lfm2.5-thinking doesn't reliably follow that instruction every
        time; _ensure_next_step_facts_present is a deterministic
        backstop that appends the real location/quest name whenever the
        model's own text doesn't already contain them, and is a no-op
        when it does.
        """
        import ai.dm_agent as dm_agent_module
        next_step = {"is_puzzle": True, "location_name": "The Sunken Archive", "quest_name": "The Archive's Recess", "clue": "riddle text"}
        missing_both = dm_agent_module._ensure_next_step_facts_present(
            "The enigmatic site whispers its truth through shadows.", next_step,
        )
        self.assertIn("The Sunken Archive", missing_both)
        self.assertIn("The Archive's Recess", missing_both)

        already_named = dm_agent_module._ensure_next_step_facts_present(
            "At the Sunken Archive, whispers of The Archive's Recess linger in the dark.", next_step,
        )
        self.assertEqual(already_named, "At the Sunken Archive, whispers of The Archive's Recess linger in the dark.")

