    async def test_divine_smite_adds_bonus_damage_and_spends_a_slot_only_on_hit(self):
        import sessions
        sessions.end_session(-999)
        user_id = 900477
        make_basic_character(
            user_id, "Smiter", char_class="Paladin", current_location="crossroads_tavern",
            armor_class=18,
        )
        db.update_character(user_id, -999, level=2, spell_slots_max=2, spell_slots_current=2)

        enemy_id = -2_500_051
        enemy = {
            "telegram_user_id": enemy_id, "name": "Dummy", "dexterity": 10, "strength": 10,
            "armor_class": 1, "proficiency_bonus": 2,  # guaranteed hits
            "hp_current": 200, "hp_max": 200, "is_ai": 1, "monster_key": "goblin",
        }
        player = db.get_character(user_id, -999)
        player["telegram_user_id"] = user_id
        session = sessions.start_session(-999, [player, enemy], {user_id: "party", enemy_id: "enemy"})
        session.turn_order = [user_id, enemy_id]
        session.current_turn_index = 0

        sink = []
        await bot._do_divine_smite(FakeUpdate(user_id, "divine smite", sink))
        sink2 = []
        # Forced roll of 20 guarantees a hit -- without this, a natural 1
        # (1/20 chance, an automatic miss in 5E regardless of AC) made
        # this test genuinely flaky (confirmed live 2026-07-16: failed
        # under real random rolls in an otherwise-clean full suite run).
        #
        # Real test-infrastructure gap found 2026-08-21 (previously
        # believed a "pre-existing, unrelated hang" -- actually caused
        # by the ATB "active battle flow" rewrite, v1.27.295): a crit's
        # real flavor narration is deferred to a background
        # asyncio.to_thread(narrate_action, ...) job so _do_attack
        # itself returns instantly in production -- but
        # unittest.IsolatedAsyncioTestCase's per-test event loop still
        # waits for that background thread to finish at teardown
        # (confirmed: this is real, documented asyncio.run() executor-
        # shutdown behavior, not a bug in this test or in production,
        # where the bot's event loop runs continuously and never tears
        # down per-request). Mocking narrate_action avoids the real
        # 200s Ollama timeout at teardown. bot._advance_turn_and_resolve_
        # ai_turns also mocked (2026-08-22) -- this is_ai goblin dummy
        # would otherwise take its own real counter-turn, which can
        # itself queue a real background narration task that
        # occasionally hasn't finished by the time the narrate_action
        # mock above goes out of scope, still hanging at teardown
        # (confirmed real via direct stress-testing, ~1/8 runs).
        # await _drain_narration_queue() (2026-08-22) -- mocking
        # narrate_action alone isn't enough; see its own docstring.
        from unittest.mock import patch, AsyncMock
        with patch("bot.narrate_action", return_value="A blow lands."), \
             patch("bot._advance_turn_and_resolve_ai_turns", new=AsyncMock()):
            await bot._do_attack(
                FakeUpdate(user_id, "I attack the dummy", sink2), "I attack the dummy", forced_roll=20
            )
            await _drain_narration_queue()

        self.assertLess(enemy["hp_current"], 200)
        self.assertEqual(db.get_character(user_id, -999)["spell_slots_current"], 1)
        sessions.end_session(-999)

    async def test_stale_narration_dropped_once_its_own_fight_has_ended(self):
        """
        Real dev-bridge report (2026-08-22, Coffee, screenshot): "The
        battle is over why is it still giving narrations?" Ollama is
        single-slot and can take 30-160s+ per call; _post_narrated's
        real flavor line is enqueued onto a per-CHAT (not per-fight)
        queue, so a long fight can leave real flavor lines still
        pending well after the fight's own mechanical resolution has
        already finished. The deterministic mechanical result already
        posted immediately (no game fact rides on the flavor line), so
        once the fight an action belonged to has genuinely ended by
        the time its flavor line is ready, it's dropped instead of
        delivered late and confusing.
        """
        import sessions
        from unittest.mock import patch, AsyncMock
        sessions.end_session(-999)
        user_id = 900479
        make_basic_character(user_id, "StaleNarrationTester", current_location="crossroads_tavern")
        enemy_id = -2_500_052
        enemy = {
            "telegram_user_id": enemy_id, "name": "Dummy", "dexterity": 10, "strength": 10,
            "armor_class": 1, "proficiency_bonus": 2, "hp_current": 200, "hp_max": 200,
            "is_ai": 1, "monster_key": "goblin",
        }
        player = db.get_character(user_id, -999)
        player["telegram_user_id"] = user_id
        session = sessions.start_session(-999, [player, enemy], {user_id: "party", enemy_id: "enemy"})
        session.turn_order = [user_id, enemy_id]
        session.current_turn_index = 0

        sink = []
        with patch("bot.narrate_action", return_value="A vivid, real flavor line."), \
             patch("bot.narration_cache.lookup", return_value=None), \
             patch("bot._advance_turn_and_resolve_ai_turns", new=AsyncMock()):
            await bot._do_attack(
                FakeUpdate(user_id, "I attack the dummy", sink), "I attack the dummy", forced_roll=15,
            )
            # The real fight ends BEFORE the queued flavor line is
            # actually delivered -- exactly the real timing gap this
            # fix closes.
            sessions.end_session(-999, session)
            await _drain_narration_queue()

        self.assertFalse(any("A vivid, real flavor line." in m for m in sink), sink)

