    async def test_gathering_credits_a_companion_favor_regardless_of_current_location(self):
        """
        Real design point: a companion travels with the party, not a
        location -- gather crediting for a companion favor must not
        require standing at any particular spot, unlike a real location
        board quest. Own chat_id (board_quests aren't otherwise isolated
        per test the way character rows are, since a Companion Favor's
        location_id is keyed only by npc_id+chat_id, not by player).
        """
        from unittest.mock import patch
        import board_quests
        chat_id = -999041
        user_id = 900970
        make_basic_character(user_id, "FavorGatherer", chat_id=chat_id, current_location="crossroads_tavern")
        party_id = db.create_party(user_id, chat_id)
        companion_id = -900971
        make_basic_character(companion_id, "Wren Hollowbrook", chat_id=chat_id, current_location="hollow_stump_shrine", is_ai=True)
        db.update_character(companion_id, chat_id, party_id=party_id)

        favor = board_quests.get_or_generate_companion_favor(bot.CAMPAIGN, "wren_hollowbrook", chat_id)
        self.assertEqual(favor["objective_type"], "gather_material")  # confirmed above: always gather here
        db.accept_board_quest(favor["board_quest_id"], user_id, chat_id)
        before_affinity = db.get_relationship(user_id, chat_id, "wren_hollowbrook")["affinity"]

        # The favor's own synthetic location_id (companion_favor:wren_hollowbrook) never matches any real
        # location -- the player's REAL current_location just needs the actual material to gather at all, which
        # naturally proves this credits regardless of the favor's own (unmatchable) location_id.
        db.update_character(user_id, chat_id, current_location="hollow_stump_shrine")
        sink = []
        with patch("bot.narrate_skill_check", return_value="A quiet, successful gathering."):
            for _ in range(favor["objective_count"]):
                await bot._do_gather(
                    FakeUpdate(user_id, "gather moonpetal", sink, chat_id=chat_id), "gather moonpetal", forced_roll=20,
                )
        after = db.get_relationship(user_id, chat_id, "wren_hollowbrook")
        self.assertEqual(after["affinity"] - before_affinity, board_quests.COMPANION_FAVOR_REWARD_AFFINITY)
        completed = db.get_active_board_quests(favor["location_id"], chat_id, favor["day_key"], tier="daily")
        self.assertTrue(any(q["board_quest_id"] == favor["board_quest_id"] and q["completed_at"] for q in completed))
        character = db.get_character(user_id, chat_id)
        self.assertEqual(character["inventory"].get("moonpetal", 0), 0)  # delivered, not kept

    async def test_gathering_credits_a_favor_a_different_party_member_accepted(self):
        """
        Real live bug (2026-08-23, Coffee, screenshot: "I just
        completed this task and it didn't recognize that I did it. I
        had two successful gathering of bait" -- the favor still
        showed "(1 of 2) — being handled by Laurienna"). Root cause:
        gather crediting only ever checked the CURRENT gatherer's own
        accepted board quests -- a different real party member
        (Laurienna) had actually accepted this exact favor, so
        Coffee's own gathering never even looked at it. Same real gap
        already fixed for defeat_monster crediting in v1.27.328, just
        missed here. Credit goes to whoever ACCEPTED it (Laurienna),
        matching the defeat_monster path's own precedent; the material
        comes out of whoever actually GATHERED it (Coffee).
        """
        from unittest.mock import patch
        import board_quests
        chat_id = -999056
        accepter_id = 901010
        gatherer_id = 901011
        make_basic_character(accepter_id, "FavorAccepterLaurienna", chat_id=chat_id, current_location="stonearch_bridge")
        party_id = db.create_party(accepter_id, chat_id)
        make_basic_character(gatherer_id, "FavorGathererCoffee", chat_id=chat_id, current_location="stonearch_bridge")
        db.update_character(gatherer_id, chat_id, party_id=party_id)
        companion_id = -901012
        make_basic_character(companion_id, "Sarah", chat_id=chat_id, current_location="crossroads_tavern", is_ai=True)
        db.update_character(companion_id, chat_id, party_id=party_id)

        favor = db.create_board_quest(
            board_quests.COMPANION_FAVOR_LOCATION_PREFIX + "sera_wanderer", chat_id, "test-day",
            "Could use a hand gathering Bait", "...", "sera_wanderer",
            "gather_material", "bait", 2, 0, 0, tier="daily",
            reward_affinity=board_quests.COMPANION_FAVOR_REWARD_AFFINITY,
        )
        db.accept_board_quest(favor["board_quest_id"], accepter_id, chat_id)  # Laurienna accepts
        before_affinity = db.get_relationship(accepter_id, chat_id, "sera_wanderer")["affinity"]

        sink = []
        with patch("bot.narrate_skill_check", return_value="A quiet, successful gathering."):
            for _ in range(favor["objective_count"]):
                await bot._do_gather(  # Coffee gathers, never having accepted the favor himself
                    FakeUpdate(gatherer_id, "gather bait", sink, chat_id=chat_id), "gather bait", forced_roll=20,
                )
        after_affinity = db.get_relationship(accepter_id, chat_id, "sera_wanderer")["affinity"]
        self.assertEqual(after_affinity - before_affinity, board_quests.COMPANION_FAVOR_REWARD_AFFINITY)
        completed = db.get_active_board_quests(favor["location_id"], chat_id, favor["day_key"], tier="daily")
        self.assertTrue(any(q["board_quest_id"] == favor["board_quest_id"] and q["completed_at"] for q in completed))
        # The bait came out of whoever actually gathered it, not the accepter (who never had it).
        self.assertEqual(db.get_character(gatherer_id, chat_id)["inventory"].get("bait", 0), 0)

    async def test_gathering_credits_a_players_own_quest_and_a_partys_favor_from_one_gather(self):
        """
        Real live bug (2026-08-23, Coffee, screenshot: "I completed this
        task and it didnt credit it" -- gathered 3x Moonpetal Flower,
        which correctly bumped his OWN personal board quest ("[Monthly]
        A supply run for Moonpetal Flower", 28/65), but a party-mate's
        Companion Favor for the same material (Wren's favor, accepted by
        Laurienna) stayed stuck at 0/3). Root cause: the crediting loop
        `break`d after the first matching candidate -- a player's own
        personal board quest for the same material at the same location
        is common (both draw from the location's one resource node) and
        always sorted first, so it silently ate the only credit every
        time, regardless of whether a party favor also matched. Fixed to
        credit every real match, same as _award_victory_xp already does
        for defeat_monster favors (no break there either).
        """
        from unittest.mock import patch
        import board_quests
        chat_id = -999049
        gatherer_id = 900986
        accepter_id = 900987
        make_basic_character(gatherer_id, "OwnQuestGatherer", chat_id=chat_id, current_location="hollow_stump_shrine")
        party_id = db.create_party(gatherer_id, chat_id)
        make_basic_character(accepter_id, "PartyFavorAccepter", chat_id=chat_id, current_location="crossroads_tavern")
        db.update_character(accepter_id, chat_id, party_id=party_id)
        companion_id = -900988
        make_basic_character(companion_id, "Wren Hollowbrook", chat_id=chat_id, current_location="hollow_stump_shrine", is_ai=True)
        db.update_character(companion_id, chat_id, party_id=party_id)

        # The gatherer's own personal board quest at his own location -- this is what used to eat the credit.
        own_quest = db.create_board_quest(
            "hollow_stump_shrine", chat_id, "test-day",
            "A supply run for Moonpetal Flower", "...", None,
            "gather_material", "moonpetal", 65, 0, 0, tier="monthly",
        )
        db.accept_board_quest(own_quest["board_quest_id"], gatherer_id, chat_id)

        # A party-mate's Companion Favor for the same material -- this is what silently never got touched.
        favor = db.create_board_quest(
            board_quests.COMPANION_FAVOR_LOCATION_PREFIX + "wren_hollowbrook", chat_id, "test-day",
            "Could use a hand gathering Moonpetal Flower", "...", "wren_hollowbrook",
            "gather_material", "moonpetal", 3, 0, 0, tier="daily",
            reward_affinity=board_quests.COMPANION_FAVOR_REWARD_AFFINITY,
        )
        db.accept_board_quest(favor["board_quest_id"], accepter_id, chat_id)
        before_affinity = db.get_relationship(accepter_id, chat_id, "wren_hollowbrook")["affinity"]

        sink = []
        with patch("bot.narrate_skill_check", return_value="A quiet, successful gathering."):
            for _ in range(favor["objective_count"]):
                await bot._do_gather(
                    FakeUpdate(gatherer_id, "gather moonpetal", sink, chat_id=chat_id), "gather moonpetal", forced_roll=20,
                )

        updated_own = db.get_active_board_quests("hollow_stump_shrine", chat_id, "test-day", tier="monthly")
        own_row = next(q for q in updated_own if q["board_quest_id"] == own_quest["board_quest_id"])
        self.assertGreater(own_row["progress_count"], 0)  # the personal quest still credits, same as before

        after_affinity = db.get_relationship(accepter_id, chat_id, "wren_hollowbrook")["affinity"]
        self.assertGreater(after_affinity, before_affinity)  # the party favor is now ALSO credited, not skipped
        completed_favor = db.get_active_board_quests(favor["location_id"], chat_id, "test-day", tier="daily")
        self.assertTrue(any(q["board_quest_id"] == favor["board_quest_id"] and q["completed_at"] for q in completed_favor))

    def test_companion_trust_gate_rejection_states_the_real_number_and_how_to_check_it(self):
        """
        Real dev-bridge request (2026-08-23, Coffee, screenshot of The
        Hush Below's rejection): "Can you please modify this message to
        explain to the players that an AI companion needs minimum of 40
        affinity points and then tell them they can look up the
        affinity by typing affinity." The old line ("None of your
        companions are ready to go any further... they need to trust
        this path (and you) more first") gave no real number and no
        hint how to check it -- the exact blind-gate problem the
        Affinity Menu (v1.27.327) was built to fix everywhere else.
        min_affinity is read off the gate itself (not hardcoded 40) so
        this stays correct even if campaign.json's own value changes.
        """
        chat_id = -999050
        user_id = 900989
        make_basic_character(user_id, "GateWalker", chat_id=chat_id, current_location="the_hush_below")
        party_id = db.create_party(user_id, chat_id)
        companion_id = -900990
        make_basic_character(companion_id, "Wren Hollowbrook", chat_id=chat_id, current_location="the_hush_below", is_ai=True)
        db.update_character(companion_id, chat_id, party_id=party_id)

        current = {"story_gates": {"the_deep_beyond": {"requires_companion_trust": {"min_affinity": 40}}}}
        character = db.get_character(user_id, chat_id)

        rejection = bot._check_story_gate(character, current, "the_deep_beyond")
        self.assertIsNotNone(rejection)
        self.assertIn("40", rejection)
        self.assertIn("affinity", rejection.lower())

        db.adjust_affinity(user_id, chat_id, "wren_hollowbrook", 40, event="test")
        character = db.get_character(user_id, chat_id)
        self.assertIsNone(bot._check_story_gate(character, current, "the_deep_beyond"))

    def test_breadth_trust_gate_requires_the_real_count_of_companions_above_threshold(self):
        """
        Real live request (2026-08-23, Coffee: "why not have another
        spot where 3 chars need to be affinity of 60" -- new "count"
        shape on requires_companion_trust, e.g. hollow_verge_ashen_
        reliquary -> hollow_verge_inner_sanctum). Two of three
        companions above threshold still fails; all three passes.
        """
        chat_id = -999051
        user_id = 900991
        make_basic_character(user_id, "BreadthWalker", chat_id=chat_id, current_location="hollow_verge_ashen_reliquary")
        party_id = db.create_party(user_id, chat_id)
        for offset, name in enumerate(["Wren Hollowbrook", "Pip Thistledown", "Grask Emberscale"], start=1):
            companion_id = -900991 - offset
            make_basic_character(companion_id, name, chat_id=chat_id, current_location="hollow_verge_ashen_reliquary", is_ai=True)
            db.update_character(companion_id, chat_id, party_id=party_id)

        current = {"story_gates": {"the_deep_beyond": {"requires_companion_trust": {"min_affinity": 60, "count": 3}}}}
        character = db.get_character(user_id, chat_id)

        # Zero trusted yet.
        rejection = bot._check_story_gate(character, current, "the_deep_beyond")
        self.assertIsNotNone(rejection)
        self.assertIn("3", rejection)
        self.assertIn("60", rejection)

        # Only 2 of 3 above threshold -- still fails.
        db.adjust_affinity(user_id, chat_id, "wren_hollowbrook", 60, event="test")
        db.adjust_affinity(user_id, chat_id, "pip_thistledown", 60, event="test")
        character = db.get_character(user_id, chat_id)
        self.assertIsNotNone(bot._check_story_gate(character, current, "the_deep_beyond"))

        # All 3 above threshold -- passes.
        db.adjust_affinity(user_id, chat_id, "grask_emberscale", 60, event="test")
        character = db.get_character(user_id, chat_id)
        self.assertIsNone(bot._check_story_gate(character, current, "the_deep_beyond"))

    def test_paired_trust_gate_requires_both_specific_companions_recruited_and_trusted(self):
        """
        Real live request (2026-08-23, Coffee: "another spot requiring
        two members that 'get along'" -- new "pair" shape on
        requires_companion_trust, e.g. wordless_choir_resonance_well ->
        wordless_choir_source). Fails if only one of the pair is
        recruited (even if trusted); fails if both are recruited but
        only one meets min_affinity; passes only when both are
        recruited AND both meet it.
        """
        chat_id = -999052
        user_id = 900995
        make_basic_character(user_id, "PairWalker", chat_id=chat_id, current_location="wordless_choir_resonance_well")
        party_id = db.create_party(user_id, chat_id)
        wren_id, vesh_id = -900996, -900997
        make_basic_character(wren_id, "Wren Hollowbrook", chat_id=chat_id, current_location="wordless_choir_resonance_well", is_ai=True)
        db.update_character(wren_id, chat_id, party_id=party_id)

        current = {"story_gates": {"the_deep_beyond": {
            "requires_companion_trust": {"pair": ["wren_hollowbrook", "vesh_nightglass"], "min_affinity": 40},
        }}}
        character = db.get_character(user_id, chat_id)

        # Only Wren recruited (not Vesh) -- fails even at full trust.
        db.adjust_affinity(user_id, chat_id, "wren_hollowbrook", 40, event="test")
        character = db.get_character(user_id, chat_id)
        rejection = bot._check_story_gate(character, current, "the_deep_beyond")
        self.assertIsNotNone(rejection)
        self.assertIn("Wren Hollowbrook", rejection)
        self.assertIn("Vesh Nightglass", rejection)

        # Both recruited, but Vesh below threshold -- still fails.
        make_basic_character(vesh_id, "Vesh Nightglass", chat_id=chat_id, current_location="wordless_choir_resonance_well", is_ai=True)
        db.update_character(vesh_id, chat_id, party_id=party_id)
        character = db.get_character(user_id, chat_id)
        self.assertIsNotNone(bot._check_story_gate(character, current, "the_deep_beyond"))

        # Both recruited and both at/above threshold -- passes.
        db.adjust_affinity(user_id, chat_id, "vesh_nightglass", 40, event="test")
        character = db.get_character(user_id, chat_id)
        self.assertIsNone(bot._check_story_gate(character, current, "the_deep_beyond"))

