    # -- Symmetric exponential rebirth scaling (2026-08-20, Coffee's
    #    a roguelike New-Game-Plus reference): "keep in mind when the player evolves the
    #    same thing happens for the players, eventually causing
    #    exponential growth" / "make sure all modifiers are included,
    #    damage types, attacks, abilities, spells, magic, summons,
    #    everything" / "proficiencies and skills also... this is why
    #    'breaking the game' mechanics in needed" / "make sure to use
    #    the elemental system and resistences too." ------------------

    def test_rebirth_power_multiplier_compounds_not_linear(self):
        from rules.leveling import rebirth_power_multiplier, REBIRTH_POWER_GROWTH_RATE
        self.assertEqual(rebirth_power_multiplier(0), 1.0)
        self.assertEqual(rebirth_power_multiplier(1), REBIRTH_POWER_GROWTH_RATE)
        self.assertEqual(rebirth_power_multiplier(3), REBIRTH_POWER_GROWTH_RATE ** 3)
        # Compounding, not additive -- rebirth 2 must be MORE than double rebirth 1's bonus.
        self.assertGreater(rebirth_power_multiplier(2) - 1.0, 2 * (rebirth_power_multiplier(1) - 1.0))

    def test_world_damage_multiplier_and_resistance_now_compound_symmetrically(self):
        """world_damage_multiplier/world_resistance_pct (the world's own side) now share the exact same compounding rate as rebirth_power_multiplier (the player's side) -- a real, symmetric arms race, not two arbitrarily different curves."""
        from rules.leveling import world_damage_multiplier, world_resistance_pct, rebirth_power_multiplier
        for r in (0, 1, 3, 5):
            self.assertEqual(world_damage_multiplier(r), rebirth_power_multiplier(r))
        self.assertEqual(world_resistance_pct(0), 0.0)
        # r=1 is still below the 100% cap below, so it still directly
        # tracks rebirth_power_multiplier's own uncapped rate here.
        self.assertAlmostEqual(world_resistance_pct(1), (rebirth_power_multiplier(1) - 1.0) * 100)

    def test_world_resistance_pct_never_exceeds_100_even_though_the_underlying_curve_is_exponential(self):
        """
        Real bug found and fixed (2026-09-14, proactive audit): world_
        resistance_pct's own exponential curve (1.5^r) vastly outpaces
        magic_penetration_pct's linear, 100%-at-rebirth-10 counter --
        uncapped, this clamped rules.combat.apply_damage_type_modifier's
        `elemental_pct * (1 - penetration)` to a flat 100% wall for
        rebirths 2 through 9 (zero real effect from any penetration
        investment for 8 straight tiers), and separately made
        elemental_overflow_heal's OWN uncapped copy of that same product
        hand monsters back 66%-393% of the player's own raw damage as
        free HP from rebirth 3 onward -- confirmed via real computed
        numbers before this fix existed. Capping this function's own
        output at 100 fixes both: a smooth 80/70/60/50/40/30/20/10/0%
        decline from rebirth 2 through 10 instead of a flat wall then a
        cliff, and zero unintended overflow-heal from world scaling
        alone (a campaign-authored "strong in an element" monster can
        still stack on top and trigger a real, but now bounded, one).
        """
        from rules.leveling import world_resistance_pct, magic_penetration_pct
        from rules.combat import apply_damage_type_modifier, elemental_overflow_heal
        self.assertEqual(world_resistance_pct(2), 100.0)
        self.assertEqual(world_resistance_pct(9), 100.0)
        for r in range(2, 11):
            elemental_pct = world_resistance_pct(r)
            penetration = magic_penetration_pct(r) / 100.0
            self.assertLessEqual(elemental_pct * (1 - penetration), 100.0)
        # Real end-to-end proof through the actual damage pipeline, not
        # just the raw numbers: a rebirth-5 monster with ONLY the world
        # baseline resistance must deal real, nonzero, smoothly-scaled
        # damage back, and must never heal from being hit.
        for r in (2, 3, 5, 7, 9):
            defender = {"elemental_resistance_pct": {"fire": world_resistance_pct(r)}}
            attacker = {"rebirth_count": r}
            modified = apply_damage_type_modifier(100, "fire", defender, attacker)
            self.assertGreater(modified, 0, f"rebirth {r}: real penetration investment must have a visible effect")
            overflow = elemental_overflow_heal(100, "fire", defender, attacker)
            self.assertEqual(overflow, 0, f"rebirth {r}: world-baseline resistance alone must never overflow-heal the defender")

    def test_labyrinth_depth_resistance_pct_never_exceeds_100_either(self):
        """Same real bug, same fix, the Labyrinth's own independent depth-based resistance axis -- it sums additively with world_resistance_pct before either reaches apply_damage_type_modifier, and floor depth grows unbounded far faster than rebirth counts do."""
        from rules.leveling import labyrinth_depth_resistance_pct
        self.assertEqual(labyrinth_depth_resistance_pct(1), 0.0)
        self.assertLessEqual(labyrinth_depth_resistance_pct(15), 100.0)
        self.assertLessEqual(labyrinth_depth_resistance_pct(200), 100.0)
        self.assertLessEqual(labyrinth_depth_resistance_pct(2000), 100.0)

    def test_rebirth_hp_and_incoming_monster_damage_stay_in_a_bounded_ratio(self):
        """
        Real, deliberate rebalance (2026-09-14, proactive audit +
        Coffee's own follow-up: "tie world_damage_multiplier to HP's
        own rate everywhere"). Before this fix, REBIRTH_POWER_GROWTH_
        RATE (1.5x/rebirth, feeding world_damage_multiplier) badly
        undershot a real character's own HP growth (full_hp_max_for's
        recursive doubling, asymptotically ~2x/rebirth) -- confirmed via
        real numbers, the gap between them grew UNBOUNDED (a rebirth-10
        character's HP was ~2,044x baseline while incoming monster
        damage was only ~58x baseline, a 35x-and-growing-worse relative
        safety margin with no ceiling). Raised to 2.0 so the two curves
        track each other -- this proves the ratio now converges to a
        small, STABLE constant instead of diverging, across a real
        range of rebirth counts.
        """
        from rules.leveling import full_hp_max_for, world_damage_multiplier
        base_hp = full_hp_max_for("Fighter", 14, 99, 0)
        ratios = []
        for r in (1, 3, 5, 10, 15, 20):
            hp_ratio = full_hp_max_for("Fighter", 14, 99, r) / base_hp
            dmg_ratio = world_damage_multiplier(r)
            ratios.append(hp_ratio / dmg_ratio)
        # Every ratio must stay within a small, bounded band -- proves
        # this doesn't diverge to the hundreds/thousands-to-one the old
        # 1.5x rate produced (confirmed via direct measurement before
        # this fix: 8.28 at r=5, 35.44 at r=10, 149.43 at r=15).
        for ratio in ratios:
            self.assertLess(ratio, 2.5, f"hp/dmg ratio {ratio:.2f} -- the gap must stay bounded, not diverge with depth")
        # The ratio must also genuinely CONVERGE (settle down), not just
        # happen to stay under the ceiling by coincidence at these
        # specific sample points -- the last few values must be close
        # to each other.
        self.assertAlmostEqual(ratios[-1], ratios[-2], delta=0.05)

