    def test_advanced_craft_recipe_rolls_a_real_generated_item_at_fixed_tier(self):
        """
        Real Phase 7 deliverable: an advanced recipe reuses
        rules/item_generator.py (the same roll combat loot already uses)
        to produce a REAL generated item at the recipe's fixed tier on
        success, instead of a flat catalog item -- and reports missing
        materials honestly without ever rolling, same convention as the
        static RECIPES above.
        """
        from rules.crafting import resolve_advanced_craft
        character = make_basic_character(950909, "AdvancedCraftTester", char_class="Fighter", current_location="crossroads_tavern")
        result = resolve_advanced_craft(character, "masterwork_longsword", practiced_bonus=0)
        self.assertEqual(result["outcome"], "missing_materials")

        db.add_item(950909, -999, "iron_ore", 6)
        db.add_item(950909, -999, "moonpetal", 1)
        character = db.get_character(950909, -999)
        succeeded = False
        for _ in range(30):
            result = resolve_advanced_craft(character, "masterwork_longsword", practiced_bonus=50)
            if result["outcome"] == "success":
                succeeded = True
                break
        self.assertTrue(succeeded)
        self.assertEqual(result["generated_item"]["type"], "weapon")
        self.assertEqual(result["generated_item"]["rarity"], "rare")

    def test_new_advanced_recipes_cover_the_remaining_weapon_and_armor_bases(self):
        """
        Real gap (2026-09-08, per Coffee: "investigate how to forge the
        next lv of weapons / armour - if there isnt next lv weapons and
        armour available add it in"). Before this, ADVANCED_RECIPES only
        covered longsword/greataxe/chain_shirt/chain_mail/wooden_shield --
        dagger/shortsword/longbow/leather were real rules.item_generator
        bases with no recipe at all, and rapier had no base entry
        whatsoever (added alongside these recipes). Exercises every new
        recipe id through the real resolve_advanced_craft path.
        """
        from rules.crafting import resolve_advanced_craft, ADVANCED_RECIPES
        new_recipes = {
            "masterwork_dagger": "weapon", "masterwork_shortsword": "weapon",
            "masterwork_longbow": "weapon", "masterwork_leather_armor": "armor",
            "masterwork_rapier": "weapon", "duelists_rapier": "weapon",
        }
        for uid, (recipe_id, expected_type) in enumerate(new_recipes.items()):
            telegram_user_id = 950920 + uid
            character = make_basic_character(telegram_user_id, f"GearTester{uid}", char_class="Fighter", current_location="crossroads_tavern")
            recipe = ADVANCED_RECIPES[recipe_id]
            for item_id, qty in recipe["materials"].items():
                db.add_item(telegram_user_id, -999, item_id, qty)
            character = db.get_character(telegram_user_id, -999)
            succeeded = False
            for _ in range(40):
                result = resolve_advanced_craft(character, recipe_id, practiced_bonus=50)
                if result["outcome"] == "success":
                    succeeded = True
                    break
            self.assertTrue(succeeded, f"{recipe_id} never succeeded even with a +50 practiced bonus")
            self.assertEqual(result["generated_item"]["type"], expected_type, recipe_id)
            self.assertEqual(result["generated_item"]["rarity"], recipe["tier"], recipe_id)

    def test_recipe_requirement_gate_rejects_wrong_guild_and_insufficient_rebirth(self):
        """
        Real feature (2026-08-11): guild-tier ladder recipes carry
        requires_guild/min_rebirth; recipe_requirement_gate (rules/
        crafting.py) is the one shared check both _do_craft and
        _do_enchant_item (bot.py) call before spending any materials.
        """
        from rules.crafting import recipe_requirement_gate, ADVANCED_RECIPES, ENCHANT_RECIPES
        character = make_basic_character(950920, "GateTester", current_location="crossroads_tavern")

        no_guild = recipe_requirement_gate(character, ADVANCED_RECIPES["journeyman_blade"])
        self.assertIsNotNone(no_guild)
        self.assertIn("Forge Guild", no_guild)

        db.update_character(950920, -999, guild="forge_guild")
        character = db.get_character(950920, -999)
        wrong_rebirth = recipe_requirement_gate(character, ADVANCED_RECIPES["masters_plate"])
        self.assertIsNotNone(wrong_rebirth)
        self.assertIn("rebirth", wrong_rebirth.lower())

        # A Forge Guild member with 0 rebirths is still correctly gated
        # OUT of an Enchanters' Guild recipe, not just an under-leveled one.
        wrong_guild_enchant = recipe_requirement_gate(character, ENCHANT_RECIPES["enchant_greater_ward"])
        self.assertIsNotNone(wrong_guild_enchant)
        self.assertIn("Enchanters' Guild", wrong_guild_enchant)
        # Real grammar bug (2026-09-11, found building the Blacksmith/
        # Alchemy category screens -- this text is now actually shown
        # to players as a locked-recipe explanation): 6 of 7 real guild
        # names already start with "The " (guilds.GUILDS), so this used
        # to read "the The Forge Guild" -- same "the The X" bug class
        # already fixed once for quest titles and key items elsewhere.
