    # -- Real-time mid-fight formation switching (2026-08-01, per Coffee:
    #    "let the party use formations to move forward and pull back in
    #    battle... it shudnt cost them a turn... Run, Give, Formation,
    #    Equip"). ---------------------------------------------------------
    def test_formation_command_naming_a_known_companion_is_not_shadowed_by_talk_npc(self):
        """
        Real live bug, caught via topic-activity monitoring (2026-08-08):
        a real player said "Pull vesh back to the back row" and later
        "Move Vesh to the backrow" -- both came back as talk_npc, and a
        Dev-topic screenshot from the same player confirmed it: "I have
        not seen any indication that this action has worked. We are
        trying to move Vesh to the back row during battle." Root cause:
        the battle-formation block used to sit AFTER the known-NPC-name
        loop, so ANY formation command naming a real companion -- which
        is nearly always, since you have to say who to move -- got
        intercepted as talk_npc first. Separately, "pull X back to the
        back/front row" (as opposed to a bare trailing "...back") never
        matched the old pull-back regex at all, since it required the
        message to literally END in "back". Both fixed together; this
        also guards the bare "back row"/"front row" mention fallback
        doesn't win over a real name just because "back row" happens to
        be a substring of "...to the back row".
        """
        npc_names = ["Vesh", "Zara"]
        r = _keyword_fallback("Pull vesh back to the back row", npc_names)
        self.assertEqual(r["action"], "set_back_row")
        self.assertEqual((r.get("target") or "").lower(), "vesh")

        r = _keyword_fallback("Move Vesh to the backrow", npc_names)
        self.assertEqual(r["action"], "set_back_row")
        self.assertEqual((r.get("target") or "").lower(), "vesh")

        r = _keyword_fallback("pull vesh back to the front row", npc_names)
        self.assertEqual(r["action"], "set_front_row")
        self.assertEqual((r.get("target") or "").lower(), "vesh")

        # No regression: talking to a known NPC by name still works.
        r = _keyword_fallback("Say hello to Vesh", npc_names)
        self.assertEqual(r["action"], "talk_npc")
        r = _keyword_fallback("Talk to Vesh about the quest", npc_names)
        self.assertEqual(r["action"], "talk_npc")

    def test_formation_command_with_bare_trailing_back_or_up_names_the_target(self):
        """
        Real live bug (2026-08-11, topic-monitor report), same shape as
        the "Pull vesh back to the back row" fix above but for "move"
        with no "to the row" phrasing at all: "Move laurienna back" came
        back as "move" (the LOCATION-travel action) instead of a
        formation change, right after "Move Sarah to front row" (which
        DOES have "to ... row" phrasing) correctly worked. Root cause:
        the name-extraction loop only recognized "to the back"/"in the
        front"/etc. cut phrases, never a bare trailing "back"/"up" the
        way "pull X back" already did.
        """
        r = _keyword_fallback("Move laurienna back", ["Laurienna"])
        self.assertEqual(r["action"], "set_back_row")
        self.assertEqual((r.get("target") or "").lower(), "laurienna")

        r = _keyword_fallback("Move Zara up", ["Zara"])
        self.assertEqual(r["action"], "set_front_row")
        self.assertEqual((r.get("target") or "").lower(), "zara")

        # No regression: the existing bare "move up"/"move to back row"
        # (no name -- assumed to mean the speaker's own character) still
        # work exactly as before.
        r = _keyword_fallback("move up", [])
        self.assertEqual(r["action"], "set_front_row")
        self.assertIsNone(r.get("target"))
        r = _keyword_fallback("Move to back row", [])
        self.assertEqual(r["action"], "set_back_row")
        self.assertIsNone(r.get("target"))

    def test_formation_command_with_bare_trailing_forward_names_the_target(self):
        """
        Real live bug (2026-08-11, same-day topic-monitor report):
        "Move zara forward" came back as plain "move" (travel) right
        next to a correctly-classified "Move elduinn to the backrow" --
        the exact same bare-trailer gap as "back"/"up" above, just a
        third natural synonym ("forward" == "to the front") that was
        never added to _MOVE_BARE_TRAILERS.
        """
        r = _keyword_fallback("Move zara forward", ["Zara"])
        self.assertEqual(r["action"], "set_front_row")
        self.assertEqual((r.get("target") or "").lower(), "zara")

    def test_formation_command_to_backrow_no_the_names_the_target(self):
        """
        Real live bug (2026-08-20, topic-activity monitoring): "Move
        Ravenloft to backrow" came back as plain "move" (travel)
        instead of a formation change. Root cause: every existing cut
        required either "the" ("to the back row") or a two-word "back
        row" -- "to backrow" (no "the", one word) matched none of them,
        a spacing variant neither the original "to the backrow" fix nor
        the later bare-trailer/"forward" fixes covered either
        (_MOVE_BARE_TRAILERS only matches a trailing bare "back", not
        "backrow"). Covers both the "to backrow" and bare "X backrow"
        (no "to") phrasings.
        """
        r = _keyword_fallback("Move Ravenloft to backrow", ["Ravenloft"])
        self.assertEqual(r["action"], "set_back_row")
        self.assertEqual((r.get("target") or "").lower(), "ravenloft")

        r2 = _keyword_fallback("Move Ravenloft backrow", ["Ravenloft"])
        self.assertEqual(r2["action"], "set_back_row")
        self.assertEqual((r2.get("target") or "").lower(), "ravenloft")

        r3 = _keyword_fallback("Move Zara to frontrow", ["Zara"])
        self.assertEqual(r3["action"], "set_front_row")
        self.assertEqual((r3.get("target") or "").lower(), "zara")

    def test_tactical_phrasing_maps_to_formation_not_flee(self):
        self.assertEqual(_keyword_fallback("pull back", [])["action"], "set_back_row")
        result = _keyword_fallback("pull Zara back", [])
        self.assertEqual(result["action"], "set_back_row")
        self.assertEqual(result["target"], "Zara")
        self.assertEqual(_keyword_fallback("cover me", [])["action"], "set_back_row")
        self.assertEqual(_keyword_fallback("fall back", [])["action"], "set_back_row")
        self.assertEqual(_keyword_fallback("push up", [])["action"], "set_front_row")
        self.assertEqual(_keyword_fallback("hold the line", [])["action"], "set_front_row")
        self.assertEqual(_keyword_fallback("move up", [])["action"], "set_front_row")
        # No regression: real flee phrasing is unaffected.
        self.assertEqual(_keyword_fallback("flee the fight", [])["action"], "flee")
        self.assertEqual(_keyword_fallback("run away", [])["action"], "flee")

    def test_flee_recognizes_fallback_run_and_runaway_as_bare_words(self):
        """
        Real dev-bridge request (2026-08-23, Coffee's own literal
        example): "when we say fallback, or run or runaway, signifies
        AI players to run." "fallback" (one word) is deliberately
        distinct from the existing "fall back" (two words, already
        claimed by set_back_row above) -- no collision.
        """
        self.assertEqual(_keyword_fallback("Fallback!", [])["action"], "flee")
        self.assertEqual(_keyword_fallback("Runaway!", [])["action"], "flee")
        self.assertEqual(_keyword_fallback("Run!", [])["action"], "flee")
        # Word-boundary safety: must not fire on an unrelated word merely containing "run".
        self.assertNotEqual(_keyword_fallback("We are running out of torches.", [])["action"], "flee")
        # False-positive guard: an unrelated sentence ending in "back"
        # after an earlier "pull " must not misfire as a formation command.
        self.assertNotEqual(
            _keyword_fallback("I pull the lever, then head back to the tavern.", [])["action"],
            "set_back_row",
        )

