        # XP past that threshold and let the real level-up path apply it.
        target_level = next(
            lvl for lvl in range(2, 10)
            if "scorching_ray" in spells.spells_unlocked_at_level("sorcerer", lvl)
        )
        db.add_xp(user_id, -999, XP_THRESHOLDS[target_level])
