    async def test_private_dm_to_the_bot_gets_a_real_getting_started_reply(self):
        """
        Real gap found 2026-08-08 (per Coffee: "if someone messages the
        Bot it serves the same purpose as getting started"): before
        this, ANY private DM to the bot -- including Telegram's own
        auto-sent /start on first opening a chat with it -- got
        silently dropped by _route_text_message, since a private chat's
        message_thread_id is always None, same as the home group's Main
        topic ("human-to-human only"). Both a plain DM and /start must
        now point the user at joining the main group or adding the bot
        to their own.
        """
        sent = []

        class _StubChat:
            id = -7001
            type = "private"

            async def send_message(self, text, parse_mode=None):
                sent.append(text)

        stub_chat = _StubChat()
        msg = SimpleNamespace(text="hi", message_thread_id=None)
        update = SimpleNamespace(effective_chat=stub_chat, effective_user=SimpleNamespace(id=701),
                                  effective_message=msg)
        await bot._route_text_message(update, SimpleNamespace(bot=None, user_data={}, args=[]))
        self.assertTrue(any(bot._PUBLIC_WORLD_INVITE_LINK in t for t in sent))
        self.assertTrue(any("add me" in t.lower() for t in sent))

        sent.clear()
        start_update = SimpleNamespace(effective_chat=stub_chat, effective_user=SimpleNamespace(id=701))
        await bot.start_command(start_update, SimpleNamespace(bot=None, user_data={}, args=[]))
        self.assertTrue(any(bot._PUBLIC_WORLD_INVITE_LINK in t for t in sent))

    def test_dm_getting_started_text_has_no_unescaped_markdown_entities(self):
        """
        Real live bug -- two real incidents, same root cause, 13 days
        apart. The FIRST fix attempt (v1.27.97, 2026-08-08) added a
        backslash before the underscore in "@PandoraMMO\\_Bot", believing
        that escaped it -- but Telegram's LEGACY parse_mode="Markdown"
        (this whole codebase's only parse_mode) has NO backslash-escape
        mechanism at all (that's a MarkdownV2-only feature); a `\\_` there
        is just a literal backslash character immediately followed by a
        real, still-unclosed italic-opening underscore. That first "fix"
        never actually worked -- confirmed by finding real
        "Can't parse entities" crashes in bot_live_tmp.log from
        2026-08-10, two full days AFTER the v1.27.97 commit, meaning
        every real private-chat DM silently got only the generic
        unhandled-error fallback instead of this text, undetected, for
        13 days until scripts/check_error_log.py (built 2026-08-21
        specifically to catch this class of silent regression) surfaced
        it. Real fix this time: the username is wrapped in a code span
        (`@PandoraMMO_Bot`) instead -- Telegram does not parse entities
        inside a code span, so the real underscore in the actual
        username is just literal text there, no escaping possible or
        needed. This checks the actual string content (a stubbed
        send_message can't catch this class of bug -- it never touches
        Telegram's real entity parser): no bare underscore outside a
        code span, and every run of literal (non-double) '*' outside a
        code span is balanced.
        """
        text = bot._DM_GETTING_STARTED_TEXT
        outside_code_spans = re.sub(r"`[^`]*`", "", text)
        bare_underscores = re.findall(r"_", outside_code_spans)
        self.assertEqual(bare_underscores, [],
                          "found a bare '_' outside a code span -- Telegram's legacy Markdown "
                          "parser has no escape mechanism and treats it as an unclosed italic "
                          "delimiter, rejecting the whole message")
        single_asterisks = re.findall(r"(?<!\*)\*(?!\*)", outside_code_spans)
        self.assertEqual(len(single_asterisks) % 2, 0,
                          "odd number of single '*' markers -- Telegram's legacy Markdown parser "
                          "will fail to find a matching close for an unpaired one")

    async def test_dm_and_group_welcome_both_link_the_real_github_repo(self):
        """
        Real gap found 2026-09-09 (Coffee, asked directly): GitHub ->
        Telegram was already fully covered (README/SETUP_GUIDE point at
        joining the main group), but nothing in the BOT ITSELF ever
        pointed a curious player back at the source repo -- bot.py had
        zero mentions of "github" anywhere. Both real onboarding
        surfaces (a private DM's getting-started text, and the message
        sent the moment an admin adds this bot to a new group) now
        include the real repo URL.
        """
        self.assertIn(bot._GITHUB_REPO_URL, bot._DM_GETTING_STARTED_TEXT)

        chat_id, fake_bot_id = -5103, 999998

        class _OnboardingFakeBot:
            def __init__(self, bot_id):
                self.id = bot_id
                self.sent = []

            async def send_message(self, chat_id, text, message_thread_id=None, parse_mode=None):
                self.sent.append(text)

        tg_bot = _OnboardingFakeBot(fake_bot_id)
        ctx = SimpleNamespace(bot=tg_bot, user_data={}, args=[])
        added = SimpleNamespace(
            chat=SimpleNamespace(id=chat_id, title="Another Test Group"),
            old_chat_member=SimpleNamespace(status="left"),
            new_chat_member=SimpleNamespace(status="member", user=SimpleNamespace(id=fake_bot_id)),
        )
        await bot.bot_added_to_group_handler(
            SimpleNamespace(effective_chat=None, effective_user=None, my_chat_member=added), ctx,
        )
        self.assertTrue(any(bot._GITHUB_REPO_URL in t for t in tg_bot.sent))

    def test_get_party_members_does_not_leak_across_tenant_chats(self):
        """
        Real cross-tenant leak, found and fixed 2026-08-08 (multi-tenant
        audit): bot._get_party_members() used to have no chat_id filter
        at all, returning every active character across EVERY tenant
        chat -- since this feeds combat targeting, dueling, and "give
        item to nearby party member" (via
        _get_combat_eligible_party_members), two different tenant
        chats' characters could target/duel/give-items to each other.
        Two characters made in two different real chat_ids here --
        each chat's own _get_party_members(chat_id) call must see only
        its own character, never the other chat's.
        """
        chat_a, chat_b = -999601, -999602
        make_basic_character(970601, "TenantA_Hero", chat_id=chat_a, current_location="crossroads_tavern")
        make_basic_character(970602, "TenantB_Hero", chat_id=chat_b, current_location="crossroads_tavern")

        members_a = bot._get_party_members(chat_a)
        members_b = bot._get_party_members(chat_b)

        names_a = {m["name"] for m in members_a}
        names_b = {m["name"] for m in members_b}
        self.assertIn("TenantA_Hero", names_a)
        self.assertNotIn("TenantB_Hero", names_a)
        self.assertIn("TenantB_Hero", names_b)
        self.assertNotIn("TenantA_Hero", names_b)

        eligible_a = bot._get_combat_eligible_party_members("crossroads_tavern", chat_a)
        self.assertIn("TenantA_Hero", {m["name"] for m in eligible_a})
        self.assertNotIn("TenantB_Hero", {m["name"] for m in eligible_a})

