    def test_sneak_attack_damage_scales_with_level_in_a_real_attack(self):
        from unittest.mock import patch
        attacker_low = {
            "name": "Lowbie", "char_class": "Rogue", "level": 1, "strength": 10, "dexterity": 10,
        }
        attacker_high = {
            "name": "Highroller", "char_class": "Rogue", "level": 10, "strength": 10, "dexterity": 10,
        }
        weapon = {"ability": "strength", "damage_dice": "1d8", "damage_bonus": 0}
        with patch("rules.dice.random.randint", return_value=4):
            defender_low = {"name": "Target", "armor_class": 1, "hp_current": 200}
            result_low = resolve_attack(attacker_low, defender_low, weapon, advantage=True)
            defender_high = {"name": "Target", "armor_class": 1, "hp_current": 200}
            result_high = resolve_attack(attacker_high, defender_high, weapon, advantage=True)
        # Fixed die value 4: level 1 = 1 sneak die (4) + weapon (4) = 8 pre-scale,
        # level 10 = 5 sneak dice (20) + weapon (4) = 24 pre-scale -- a +16 delta
        # before any player-power scaling. The 2026-07-26 rebalance (per Coffee:
        # "rebalance everything... all skills and abilities") multiplies a real
        # character's own damage by power_scale_ratio(level, rebirth_count), so
        # each side now also scales by its OWN attacker's ratio -- recomputed
        # here via the real function rather than hardcoded, so this stays valid
        # if the ratio formula itself is ever retuned again.
        #
        # Real stale-test fix (2026-09-09, found chasing a real, confirmed
        # failure -- 114 != 105 for the level-10 case): neither attacker
        # dict here sets `formation_row`, and formation_damage_bonus_pct's
        # own real, documented default (2026-08-14, "Smarter, Formation-
        # Aware Enemy AI" -- per Coffee: "front row used for aggressors")
        # treats a MISSING formation_row exactly like "front row" (a real
        # solo-fight fallback, not a bug), applying config.FRONT_ROW_
        # DAMAGE_BONUS_PCT before the power-scale multiply. This test
        # predates that feature and never accounted for it -- the level-1
        # case only ever passed by int()-truncation coincidence (8*1.10=8.8
        # truncates back down to 8), which is exactly why only the level-10
        # case (24*1.10=26.4, truncates UP to a real extra point vs the old
        # un-bonused 24) ever surfaced the drift.
        from rules.leveling import power_scale_ratio
        front_row_multiplier = 1 + config.FRONT_ROW_DAMAGE_BONUS_PCT / 100
        expected_low = int(int(8 * front_row_multiplier) * power_scale_ratio(1, 0))
        expected_high = int(int(24 * front_row_multiplier) * power_scale_ratio(10, 0))
        self.assertEqual(result_low["damage_dealt"], expected_low)
        self.assertEqual(result_high["damage_dealt"], expected_high)

    # -- Synergy Phase 7 (2026-08-13): The Verge Warden's real signature
    #    mechanic -- can't be caught off guard by a Sneak Attack twice --
    def test_boss_with_counters_sneak_attack_negates_the_second_hit_in_a_fight(self):
        from unittest.mock import patch
        attacker = {"name": "Shadowblade", "char_class": "Rogue", "level": 1, "strength": 10, "dexterity": 14}
        weapon = {"ability": "dexterity", "damage_dice": "1d8", "damage_bonus": 0}
        defender = {"name": "The Verge Warden", "armor_class": 1, "hp_current": 1000, "counters_sneak_attack": True}
        with patch("rules.dice.random.randint", return_value=4):
            first = resolve_attack(attacker, defender, weapon, advantage=True, forced_roll=20)
            second = resolve_attack(attacker, defender, weapon, advantage=True, forced_roll=20)
            third = resolve_attack(attacker, defender, weapon, advantage=True, forced_roll=20)
        self.assertTrue(first["hit"] and second["hit"] and third["hit"])
        self.assertGreater(first["damage_dealt"], second["damage_dealt"], "the FIRST sneak attack must still land in full")
        self.assertEqual(second["damage_dealt"], third["damage_dealt"], "negated for the rest of the fight, not just once")

