    async def test_narrate_action_falls_back_when_model_returns_a_bare_placeholder(self):
        """Real live bug follow-up: narrate_action must never return "(stub)" verbatim -- it should fall back to the deterministic template, same as a real Ollama error."""
        from unittest.mock import patch
        import ai.dm_agent as dm_agent_module

        class FakeResponse:
            def raise_for_status(self):
                pass

            def json(self):
                return {"response": "(stub)"}

        mechanical_result = {"hit": False, "raw_roll": 2, "attacker": "Grask Emberscale", "defender": "Shadow Wisp 3"}
        with patch("ai.dm_agent.requests.post", return_value=FakeResponse()):
            result = dm_agent_module.narrate_action(
                {"name": "Grask Emberscale", "char_class": "Barbarian", "hp_current": 700, "hp_max": 779},
                "attack the shadow wisp", mechanical_result,
            )
        self.assertNotEqual(result.strip(), "(stub)")
        self.assertIn("Grask Emberscale", result)
        self.assertIn("Shadow Wisp 3", result)

    async def test_narration_token_cap_gives_real_headroom_over_thinking_overhead(self):
        """
        Real live bug (2026-08-13, dev-bridge screenshot, Coffee: "The
        narration cut off can you investigate this? This might be why
        the banter isn't working also."). _NARRATION_OPTIONS'
        num_predict caps thinking + visible-answer tokens TOGETHER for
        this "thinking" model (lfm2.5-thinking) -- confirmed live, real
        narration truncated mid-word ("...the weight of unsp") at
        STORY_MODE=7, well under the STORY_MODE 10 case the old 1200
        value was originally sized for (2026-07-17). Since the model's
        own reasoning length varies run-to-run independent of the
        eventual narration's length, 1200 was measurably not enough
        headroom. Confirms the real Ollama request payload actually
        carries the new, higher cap, not just that the module constant
        changed.
        """
        from unittest.mock import patch
        import ai.dm_agent as dm_agent_module

        self.assertGreaterEqual(
            dm_agent_module._NARRATION_OPTIONS["num_predict"], 2000,
            "num_predict needs real headroom over a thinking model's reasoning tokens, not just the old 1200",
        )

        captured = {}

        class FakeResponse:
            def raise_for_status(self):
                pass

            def json(self):
                return {"response": "A plain result."}

        def fake_post(*a, **k):
            captured["options"] = k.get("json", {}).get("options")
            return FakeResponse()

        character = {"name": "Grubnak", "char_class": None, "hp_current": 20, "hp_max": 20}
        result = {"hit": True, "damage_dealt": 5, "raw_roll": 12}
        with patch("ai.dm_agent.requests.post", side_effect=fake_post):
            dm_agent_module.narrate_action(character, "attacks Fenwick", result)
        self.assertEqual(captured["options"]["num_predict"], dm_agent_module._NARRATION_OPTIONS["num_predict"])

    async def test_enemy_banter_only_rolled_for_enemy_side_attackers(self):
        """
        _post_narrated must only ever ask narrate_action for banter when
        the attacker is on the "enemy" side of the fight -- never a real
        player, and never a friendly AI-controlled party companion, even
        though both take their combat turn through this exact same
        function (see _resolve_ai_turns). Forces random.random() to 0.0
        (always below ENEMY_BANTER_CHANCE) so this tests the actual side
        check, not dice luck.
        """
        import asyncio
        from unittest.mock import patch
        import sessions
        sessions.end_session(-997)
        enemy_id = -2_500_080
        companion_id = -2_500_081
        monster = {"telegram_user_id": enemy_id, "name": "BanterGoblin", "dexterity": 10, "strength": 10,
                   "hp_current": 20, "hp_max": 20, "armor_class": 10, "is_ai": 1, "monster_key": "goblin"}
        companion = {"telegram_user_id": companion_id, "name": "FriendlyAI", "dexterity": 10, "strength": 10,
                     "hp_current": 20, "hp_max": 20, "armor_class": 10, "is_ai": 1}
        session = sessions.start_session(-997, [monster, companion], {enemy_id: "enemy", companion_id: "party"})
        mechanical_result = {"hit": True, "damage_dealt": 5, "attacker": "BanterGoblin", "defender": "FriendlyAI",
                              "raw_roll": 15, "critical_hit": False, "critical_fail": False}

        captured = {}

        def fake_narrate_action(character, action_text, mech_result, recent_events=None,
                                 actor_personality=None, location_description=None, include_banter=False):
            captured["include_banter"] = include_banter
            return "The goblin swings."

        sink = []
        update = FakeUpdate(enemy_id, "n/a", sink)

        # Real flavor delivery is now a background job (2026-08-21,
        # "active battle flow") -- narrate_action isn't called inline
        # anymore, so a brief real sleep lets the queued job actually
        # run before checking what it was called with. narration_cache
        # is also forced to always miss here: it's a real, persisted
        # store (.pdrx8k2f/n.db, not reset between test runs) that a
        # long testing history can easily have warmed up past
        # MIN_VARIANTS_BEFORE_REUSE for this exact routine "hit/low
        # damage" bucket -- with random.random() also mocked to 0.0,
        # lookup()'s own CACHE_HIT_RATE roll would then always return a
        # real cached line instead of None, skipping narrate_action
        # entirely and leaving `captured` stale. This test's actual
        # target is the include_banter argument passed through, not
        # cache-hit behavior (covered elsewhere), so a forced miss is
        # the correct isolation, not a workaround.
        with patch("bot.narrate_action", fake_narrate_action), patch("bot.random.random", return_value=0.0), \
                patch("bot.narration_cache.lookup", return_value=None):
            await bot._post_narrated(update, monster, "attacks FriendlyAI", mechanical_result, session)
            await asyncio.sleep(0.2)
        self.assertTrue(captured["include_banter"], "enemy-side attacker with a below-threshold roll should get banter")

        with patch("bot.narrate_action", fake_narrate_action), patch("bot.random.random", return_value=0.0), \
                patch("bot.narration_cache.lookup", return_value=None):
            await bot._post_narrated(update, companion, "attacks BanterGoblin", mechanical_result, session)
            await asyncio.sleep(0.2)
        self.assertFalse(captured["include_banter"], "party-side (friendly AI companion) attacker must never get banter")

        sessions.end_session(-997)

