    async def test_ai_turn_narration_budget_does_not_starve_banter_after_one_real_call(self):
        """
        Real live report (2026-08-12, Coffee: "i am also not seeing
        banter still in battles"). Original root cause: AI_TURN_
        NARRATION_BUDGET_SECONDS was 45.0 back in v1.27.9 (2026-07-24),
        well under real per-call Ollama latency (46-160s+, see
        CLAUDE.md) -- turns_started_at's wall-clock deadline meant only
        the FIRST AI-narrated attack of a round could reach the
        include_banter roll; every later enemy that same round was
        guaranteed skip_narration=True. Since bumped to 180s (a real,
        separate fix), and -- as of the 2026-08-21 "active battle flow"
        redesign -- structurally can't recur at all anymore: narrate_
        action is never awaited inline inside _resolve_ai_turns_inner's
        own loop (see _post_narrated), so one enemy's real narration
        call no longer eats into wall-clock time the NEXT enemy's own
        skip_narration check reads. This test now confirms that
        real-world guarantee directly: both enemies' real (mocked)
        narrate_action calls actually run -- delivered through the
        background narration queue, same as any other combat message --
        and both get a real shot at banter.
        """
        from unittest.mock import patch
        import asyncio
        import sessions
        sessions.end_session(-995)
        enemy1_id, enemy2_id, player_id = -2_500_090, -2_500_091, 555095
        enemy1 = {"telegram_user_id": enemy1_id, "name": "FirstGoblin", "dexterity": 10, "strength": 10,
                  "hp_current": 20, "hp_max": 20, "armor_class": 10, "is_ai": 1, "monster_key": "goblin"}
        enemy2 = {"telegram_user_id": enemy2_id, "name": "SecondGoblin", "dexterity": 10, "strength": 10,
                  "hp_current": 20, "hp_max": 20, "armor_class": 10, "is_ai": 1, "monster_key": "goblin"}
        player = {"telegram_user_id": player_id, "chat_id": -995, "name": "RealPlayer", "dexterity": 10,
                  "strength": 10, "hp_current": 20, "hp_max": 20, "armor_class": 15, "is_ai": 0}
        session = sessions.start_session(
            -995, [enemy1, enemy2, player],
            {enemy1_id: "enemy", enemy2_id: "enemy", player_id: "party"},
        )
        # Force turn order so both enemies act before control returns to
        # the real player -- start_session rolls random initiative, and
        # this test needs a deterministic multi-enemy round to exercise
        # the budget, not luck of the dice.
        session.turn_order = [enemy1_id, enemy2_id, player_id]
        session.current_turn_index = 0

        calls = []

        def fake_narrate_action(character, action_text, mech_result, recent_events=None,
                                 actor_personality=None, location_description=None, include_banter=False):
            calls.append({"attacker": character["name"], "include_banter": include_banter})
            return "The goblin swings."

        sink = []
        update = FakeUpdate(enemy1_id, "n/a", sink)
        with patch("bot.narrate_action", fake_narrate_action), \
             patch("bot.random.random", return_value=0.0):
            await bot._resolve_ai_turns(update, session)
            # Real flavor delivery is a background job now -- let the
            # per-chat narration queue actually drain both enqueued jobs
            # before checking what they were called with.
            await asyncio.sleep(0.3)

        self.assertEqual(
            [c["attacker"] for c in calls], ["FirstGoblin", "SecondGoblin"],
            "both enemies in this round must reach a real narrate_action call, not just the first",
        )
        self.assertTrue(calls[0]["include_banter"])
        self.assertTrue(calls[1]["include_banter"], "second enemy's attack must still get a real shot at banter")
        sessions.end_session(-995)

    # -- Battle formation image (2026-08-09, task #9-followup) -----------
    def test_render_battle_formation_produces_a_valid_png_reflecting_real_state(self):
        """
        Real live request (per Coffee): "show the formations and
        locations of where the players are battling." Pure rendering
        check, no bot.py/network involved -- confirms real PNG bytes
        come back at the expected canvas size for a real front/back,
        boss-included roster, so a false positive here can't silently
        mean the renderer is broken.
        """
        import io
        from PIL import Image
        import battle_render
        party = [
            {"name": "Ravenloft", "hp_current": 40, "hp_max": 40, "formation_row": "front"},
            {"name": "Willowmere", "hp_current": 18, "hp_max": 30, "formation_row": "back"},
        ]
        enemies = [
            {"name": "Goblin Boss", "hp_current": 60, "hp_max": 93, "formation_row": "front", "is_boss": True},
            {"name": "Goblin Shaman", "hp_current": 10, "hp_max": 25, "formation_row": "back"},
        ]
        png_bytes = battle_render.render_battle_formation(party, enemies)
        self.assertGreater(len(png_bytes), 0)
        image = Image.open(io.BytesIO(png_bytes))
        image.verify()
        image = Image.open(io.BytesIO(png_bytes))
        self.assertEqual(image.format, "PNG")
        self.assertEqual(image.size, (battle_render.CANVAS_WIDTH, battle_render.CANVAS_HEIGHT))

