    async def test_join_battle_uses_real_current_location_not_a_stale_combat_snapshot(self):
        """
        Real live bug (2026-08-19, Coffee: "im saying join the battle
        and it says there is no battle... we are at the LONELY CAIRN").
        Confirmed live: a real human combat participant's OWN database
        row had moved on to a new location (greymoor_downs_lonely_cairn)
        while her in-memory combat participant dict still carried the
        stale location from whenever the fight actually began
        (greymoor_downs) -- _do_join_battle used to read that frozen
        in-memory copy, so a player standing at the real, current fight
        location got told there was no fight there. Now reads each
        party-side member's real, current DB row instead (real humans
        checked before AI companions, since a human's own row can't be
        silently relocated by anything else while they're mid-fight).
        """
        import sessions
        sessions.end_session(-987)
        fighter_id, joiner_id = 900952, 900953
        make_basic_character(fighter_id, "DriftedFighter", chat_id=-987, current_location="greymoor_downs")
        make_basic_character(joiner_id, "RealJoiner", chat_id=-987, current_location="greymoor_downs_lonely_cairn")
        fighter = db.get_character(fighter_id, -987)
        fighter["telegram_user_id"] = fighter_id
        # The combat snapshot still carries the OLD location the fight
        # actually started at -- never refreshed once combat began.
        fighter["current_location"] = "greymoor_downs"
        enemy = {"telegram_user_id": -2_500_099, "name": "DriftGoblin", "dexterity": 10, "strength": 10,
                 "hp_current": 25, "hp_max": 25, "armor_class": 10, "is_ai": 1, "monster_key": "goblin"}
        sessions.start_session(-987, [fighter, enemy], {fighter_id: "party", -2_500_099: "enemy"})

        # The real, current DB row has since moved on -- this is the
        # authoritative "where is this person right now" this fix reads.
        db.update_character(fighter_id, -987, current_location="greymoor_downs_lonely_cairn")

        sink = []
        update = FakeUpdate(joiner_id, "join the battle", sink, chat_id=-987)
        await bot._do_join_battle(update)

        reply = "\n".join(sink)
        self.assertNotIn("no fight", reply.lower(), f"should have joined, got: {reply!r}")
        session = sessions.get_session_for_user(-987, joiner_id)
        self.assertIsNotNone(session, "the real joiner should now be a genuine combat participant")
        sessions.end_session(-987)

    # -- Real live report (2026-08-20, Coffee, dev-bridge screenshots):
    #    "make sure all the north south east and west locations on all
    #    the different layers are correct. I don't want any locations
    #    conflicting." scripts/build_location_grid.py re-derives a
    #    fully self-consistent `directions` + `grid_position` for every
    #    location from `connections` (the one authoritative reachability
    #    list). This is the ongoing guard against it ever drifting back
    #    out of sync -- checks the REAL live campaign.json, not a fixture.
    def test_campaign_directions_have_zero_reciprocity_conflicts(self):
        OPPOSITE = {
            "north": "south", "south": "north", "east": "west", "west": "east", "up": "down", "down": "up",
        }
        conflicts = []
        for layer_name, places in bot.CAMPAIGN["locations"].items():
            for lid, info in places.items():
                for word, dest in (info.get("directions") or {}).items():
                    dest_info = places.get(dest)
                    if dest_info is None:
                        conflicts.append(f"[{layer_name}] {lid}.{word}={dest}: destination not in layer")
                        continue
                    back = (dest_info.get("directions") or {}).get(OPPOSITE[word])
                    if back != lid:
                        conflicts.append(f"[{layer_name}] {lid}.{word}={dest}: dest.{OPPOSITE[word]}={back!r}, expected {lid!r}")
        self.assertEqual(conflicts, [], "\n".join(conflicts))

    def test_campaign_grid_positions_agree_with_their_own_directions(self):
        """
        Every directed edge's two grid_position values must actually be
        adjacent in the direction claimed -- not just reciprocal, but
        geometrically consistent.

        Extended 2026-08-27 (map-coordinate overhaul, per Coffee:
        "make it feel like classic action-adventure dungeons... string paths") to also
        validate up/down -- previously skipped entirely, on the
        assumption every vertical edge shared its parent's exact
        (x, y). That assumption only actually holds for
        SAME_CELL_VERTICAL_PAIRS (the one real "same building, a
        different floor" case, Crossroads Tavern's cellar/upstairs);
        every other real up/down edge is now a genuine dungeon delve
        with its own distinct cell, using the same delta a lateral
        "south"/"north" edge would (scripts/build_location_grid.py's
        own real placement rule) -- this closes the exact validation
        gap an earlier research pass found.
        """
        import sys
        sys.path.insert(0, "scripts")
        import build_location_grid as blg

        DELTA = {"north": (0, 1), "south": (0, -1), "east": (1, 0), "west": (-1, 0),
                 "down": (0, -1), "up": (0, 1)}
        mismatches = []
        for layer_name, places in bot.CAMPAIGN["locations"].items():
            for lid, info in places.items():
                pos = info.get("grid_position")
                if pos is None:
                    continue
                for word, dest in (info.get("directions") or {}).items():
                    if word not in DELTA:
                        continue
                    dest_pos = (places.get(dest) or {}).get("grid_position")
                    if dest_pos is None:
                        continue
                    actual = (dest_pos["x"], dest_pos["y"])
                    same_cell = (dest in blg.SAME_CELL_VERTICAL_PAIRS.get(lid, ())
                                 or lid in blg.SAME_CELL_VERTICAL_PAIRS.get(dest, ()))
                    if word in ("up", "down") and same_cell:
                        expected = (pos["x"], pos["y"])  # the one real same-cell exception
                    else:
                        dx, dy = DELTA[word]
                        expected = (pos["x"] + dx, pos["y"] + dy)
                    if actual != expected:
                        mismatches.append(f"[{layer_name}] {lid}.{word}={dest}: expected grid_position {expected}, got {actual}")
        self.assertEqual(mismatches, [], "\n".join(mismatches))

