    def test_evolve_dungeon_boss_defeat_reveals_a_real_shortcut_data_shape(self):
        """
        Real event-gated live edge, ported to evolved overworld
        dungeons (2026-09-06, per Coffee: "keep going" -- a reference
        water dungeon's own real "portal opens after mini-boss defeat"
        pattern, already shipped for the Labyrinth in v1.27.529). Two
        earlier approaches were rejected for real reasons (see
        [[project_advanced_interconnected_dungeons_research]]): a live
        campaign.json mutation, and an ungated bidirectional warp. This
        is the real third option -- a plain connection written once at
        generation time, kept closed in the hub-ward direction by a
        real, per-CHARACTER story_gates/requires_cleared_location gate
        (not a live mutation, not an ungated backdoor). Statistical:
        fires on every real generation (there's only ever one boss),
        never the same edge a locked_connections gate already owns.
        """
        import copy
        for seed in range(10):
            campaign = copy.deepcopy(bot.CAMPAIGN)
            rng = random.Random(seed)
            new_id = f"goblin_warrens_evolved_bossshortcut_stat_{seed}"
            dungeon_evolve.evolve_dungeon(campaign, "goblin_warrens", new_id, "underground", rebirth_gate=1, rng=rng)
            rooms = dungeon_audit._dungeon_rooms(campaign, new_id)
            hub_id = next(rid for rid, r in rooms.items() if r.get("dungeon_hub"))
            boss_room_id = next(rid for rid, r in rooms.items() if r.get("is_boss_room"))
            boss_room = rooms[boss_room_id]
            self.assertIn(hub_id, boss_room.get("connections", []), f"seed {seed}: expected a real plain connection from the boss room back to the hub")
            self.assertEqual(boss_room.get("story_gates", {}).get(hub_id, {}).get("requires_cleared_location"), boss_room_id)

    async def test_evolve_dungeon_boss_shortcut_blocked_then_opens_once_cleared_end_to_end(self):
        """Real end-to-end companion: bot._do_move genuinely refuses the boss-room-to-hub shortcut until this character's own cleared_locations records a real win there, then allows it -- the exact same per-character mechanism sequential dungeon gating already uses elsewhere, not a new one."""
        import copy
        from unittest.mock import patch
        campaign = copy.deepcopy(bot.CAMPAIGN)
        rng = random.Random(5)
        new_id = "goblin_warrens_evolved_bossshortcut_e2e"
        dungeon_evolve.evolve_dungeon(campaign, "goblin_warrens", new_id, "underground", rebirth_gate=1, rng=rng)
        rooms = dungeon_audit._dungeon_rooms(campaign, new_id)
        hub_id = next(rid for rid, r in rooms.items() if r.get("dungeon_hub"))
        boss_room_id = next(rid for rid, r in rooms.items() if r.get("is_boss_room"))

        with patch.object(bot, "CAMPAIGN", campaign):
            user_id = 960902
            make_basic_character(user_id, "BossShortcutTester", current_location=boss_room_id)
            db.update_character(user_id, -999, visited_locations=[boss_room_id, hub_id])
            sink = []
            await bot._do_move(FakeUpdate(user_id, "", sink), f"go to {rooms[hub_id]['name']}")
            character = db.get_character(user_id, -999)
            self.assertNotEqual(character["current_location"], hub_id, "must stay blocked before this character has really cleared the boss room")

            db.mark_location_cleared(user_id, -999, boss_room_id)
            sink2 = []
            await bot._do_move(FakeUpdate(user_id, "", sink2), f"go to {rooms[hub_id]['name']}")
            character = db.get_character(user_id, -999)
            self.assertEqual(character["current_location"], hub_id, "must open once this character has really cleared the boss room")

    def test_evolve_dungeon_never_places_two_switch_lockables_in_one_room(self):
        """
        Real regression found and fixed shipping the mid-branch gate/
        key-mesh mechanics (2026-09-06): a branch root can
        independently be chosen as a switch's home by more than one
        mechanic (the pre-existing collapse-puzzle switch, the
        mid-branch gate's own source switch, and the mesh's own two
        switches all draw from the same branch-root pool). Scoped to
        `kind: "switch"` specifically, not lockables generally -- two
        different CHESTS in one room, for example, still disambiguate
        fine via `_find_lockable`'s own distinctive-name-word matching
        (different flavor text), but two switches can genuinely roll
        the identical element/name, making `_find_lockable`'s real
        "same-kind ambiguous, refuse" rule (v1.27.513) silently swallow
        whichever action a player takes there, breaking every mechanic
        sharing that room at once. `dungeon_audit.py`'s own checks
        never catch this (an ambiguous lockable is a gameplay problem,
        not a graph-structure one), so this is checked directly across
        many real seeds/sources.
        """
        import copy
        checked = 0
        for source in ("goblin_warrens", "sunken_root_caverns", "greymoor_downs"):
            for seed in range(40):
                campaign = copy.deepcopy(bot.CAMPAIGN)
                rng = random.Random(seed)
                new_id = f"{source}_evolved_switch_collision_{seed}"
                dungeon_evolve.evolve_dungeon(campaign, source, new_id, "underground", rebirth_gate=1, target_band=(20, 30), rng=rng)
                rooms = dungeon_audit._dungeon_rooms(campaign, new_id)
                checked += 1
                for room_id, room in rooms.items():
                    switch_count = sum(1 for lk in room.get("lockables", []) if lk.get("kind") == "switch")
                    self.assertLessEqual(switch_count, 1, f"{source} seed={seed}: room {room_id!r} has {switch_count} real switch lockables -- ambiguous to _find_lockable")
        self.assertGreater(checked, 0)

    def test_evolve_dungeon_sometimes_places_a_real_remote_torch_gate(self):
        """
        Real remote-gate mechanic (2026-09-01, per Coffee: "lighting a
        torch here opens a gate somewhere else"). Confirmed via the
        real data shape, not just that a switch exists: the torch's own
        `lockables` entry must live in a DIFFERENT room than whichever
        room's `locked_connections` references it -- already supported
        by the existing data model, dungeon_audit.py's own checks don't
        need to know or care. Statistical across real seeds, same
        discipline as the plain switch-gate test above.
        """
        import copy
        remote_hits = 0
        for seed in range(40):
            campaign = copy.deepcopy(bot.CAMPAIGN)
            rng = random.Random(seed)
            new_id = f"goblin_warrens_evolved_torch_stat_{seed}"
            dungeon_evolve.evolve_dungeon(campaign, "goblin_warrens", new_id, "underground", rebirth_gate=1, rng=rng)
            rooms = dungeon_audit._dungeon_rooms(campaign, new_id)
            switch_room_by_id = {
                lk["id"]: rid for rid, r in rooms.items() for lk in r.get("lockables", []) if lk.get("kind") == "switch"
            }
            for rid, room in rooms.items():
                for lockable_id in room.get("locked_connections", {}).values():
                    if lockable_id in switch_room_by_id and switch_room_by_id[lockable_id] != rid:
                        remote_hits += 1
        self.assertGreater(remote_hits, 0, "expected at least one real remote torch gate across 40 real seeds")

    def test_evolve_dungeon_sometimes_places_a_real_pressure_plate_gate(self):
        """
        Real movable-object/pressure-plate mechanic (2026-09-01, per
        Coffee: "pushing things down holes"/"filling urns"). A second,
        independent branch gate alongside the elemental switch above --
        confirmed statistically, and confirmed it never lands on the
        SAME branch as a switch when both roll on the same generation
        (the two gates are deliberately mutually exclusive per-branch,
        see dungeon_evolve.py's own plate_eligible filter).
        """
        import copy
        hits = 0
        for seed in range(20):
            campaign = copy.deepcopy(bot.CAMPAIGN)
            rng = random.Random(seed)
            new_id = f"goblin_warrens_evolved_plate_stat_{seed}"
            dungeon_evolve.evolve_dungeon(campaign, "goblin_warrens", new_id, "underground", rebirth_gate=1, rng=rng)
            rooms = dungeon_audit._dungeon_rooms(campaign, new_id)
            plate_lockables = [lk for r in rooms.values() for lk in r.get("lockables", []) if lk.get("kind") == "pressure_plate"]
            switch_lockables = [lk for r in rooms.values() for lk in r.get("lockables", []) if lk.get("kind") == "switch"]
            if plate_lockables:
                hits += 1
                # Every real plate has its own movable object sitting in the same room.
                plate_rooms = [r for r in rooms.values() if any(lk.get("kind") == "pressure_plate" for lk in r.get("lockables", []))]
                for r in plate_rooms:
                    self.assertTrue(r.get("movable_objects"), "expected a real movable object placed with the pressure plate")
                # Never the same branch id as a switch gate in the same generation.
                if switch_lockables:
                    plate_ids = {lk["id"].rsplit("_", 1)[-1] for lk in plate_lockables}
                    switch_ids = {lk["id"].rsplit("_", 1)[-1] for lk in switch_lockables}
                    self.assertTrue(plate_ids.isdisjoint(switch_ids), "a switch and a plate should never gate the same branch index")
        self.assertGreater(hits, 0, "expected at least one pressure-plate-gated evolve across 20 real seeds")
        self.assertLess(hits, 20, "expected at least one evolve WITHOUT a pressure plate across 20 real seeds -- it should be a real fraction, not every time")

    def test_evolve_dungeon_chests_can_rarely_grant_a_real_spell_tonic(self):
        """
        Real live gap found and fixed (2026-09-05, per Coffee, dev-
        bridge: "we need you to add ethers to the item list of things
        that can be won from a chest" -- same fix as rules/labyrinth.py's
        own chests, see dungeon_audit.maybe_add_spell_tonic_to_loot's
        own docstring). Statistical: across enough seeds, at least one
        real evolved-dungeon chest must grant one of the three real
        spell-tonic tiers, always on top of its existing potion/gold,
        never replacing it.
        """
        import copy
        tonic_seen = False
        for seed in range(60):
            campaign = copy.deepcopy(bot.CAMPAIGN)
            rng = random.Random(seed)
            new_id = f"goblin_warrens_evolved_tonic_stat_{seed}"
            dungeon_evolve.evolve_dungeon(campaign, "goblin_warrens", new_id, "underground", rebirth_gate=1, rng=rng)
            rooms = dungeon_audit._dungeon_rooms(campaign, new_id)
            for room in rooms.values():
                for lockable in room.get("lockables", []):
                    if lockable.get("kind") != "chest" or "greater_healing_potion" not in lockable.get("loot", {}):
                        continue
                    loot = lockable["loot"]
                    if any(tid in loot for tid in ("spell_tonic", "greater_spell_tonic", "supreme_spell_tonic")):
                        tonic_seen = True
        self.assertTrue(tonic_seen, "expected at least one real spell-tonic chest drop across 60 real seeds")

    def test_evolve_dungeon_sometimes_places_a_real_key_gate_solvable_by_construction(self):
        """
        Phase B port of rules/labyrinth.py's identical key-gate
        mechanic (2026-09-04, per Coffee: "you can have locked doors
        requireing 'keys'... keys can be dropped by enemies or found
        in another room"). Statistical, same discipline as the switch/
        plate gates above: confirms the door is consume_key, is a real
        add_key_gate wiring, never shares a branch with the switch/
        plate gate, and the key (chest loot or guaranteed drop) always
        sits in a DIFFERENT branch than the one it gates AND never in
        the switch-/plate-gated branch either -- the exact real bug
        already found and fixed in the Labyrinth's own port of this
        mechanic (a "guaranteed" find behind an unrelated existing gate
        isn't actually guaranteed without solving that gate first).
        """
        import copy
        hits = 0
        for seed in range(40):
            campaign = copy.deepcopy(bot.CAMPAIGN)
            rng = random.Random(seed)
            new_id = f"goblin_warrens_evolved_key_stat_{seed}"
            dungeon_evolve.evolve_dungeon(campaign, "goblin_warrens", new_id, "underground", rebirth_gate=1, rng=rng)
            failures = dungeon_audit.audit_dungeon(campaign, new_id)
            for check_name, check_failures in failures.items():
                self.assertFalse(check_failures, f"seed {seed}, {check_name}: {check_failures}")
            rooms = dungeon_audit._dungeon_rooms(campaign, new_id)
            door = next((lk for r in rooms.values() for lk in r.get("lockables", []) if lk.get("requires_key_item") == "labyrinth_floor_key"), None)
            if door is None:
                continue
            hits += 1
            self.assertTrue(door.get("consume_key"), "expected the per-dungeon key to be consumed on use, unlike a hand-authored story key")
            hub_id = next(rid for rid, r in rooms.items() if r.get("dungeon_hub"))
            gated_room_id = next(d for d, lid in rooms[hub_id]["locked_connections"].items() if lid == door["id"])
            key_chest_room = next(
                (rid for rid, r in rooms.items() if any(lk.get("kind") == "chest" and "labyrinth_floor_key" in lk.get("loot", {}) for lk in r.get("lockables", []))),
                None,
            )
            key_drop_room = next((rid for rid, r in rooms.items() if r.get("guaranteed_key_drop")), None)
            key_room_id = key_chest_room or key_drop_room
            self.assertIsNotNone(key_room_id, "expected the key to be findable via a real chest or a real guaranteed drop")
            self.assertNotEqual(key_room_id, gated_room_id, "the key must never sit inside the very branch it gates")
            if key_drop_room is not None:
                self.assertTrue(rooms[key_drop_room].get("monsters"), "a guaranteed key drop must sit on a room with a real monster to defeat")
            # Never inside the switch- or plate-gated branch either --
            # a locked_connections destination is never a plain,
            # freely-walkable room, so if the key room is one of those,
            # it isn't actually reachable without solving THAT gate first.
            locked_destinations = set(rooms[hub_id].get("locked_connections", {}).keys())
            self.assertNotIn(key_room_id, locked_destinations, "the key must sit in a plainly-reachable branch, not behind an unrelated existing gate")
        self.assertGreater(hits, 0, "expected at least one key-gated evolve across 40 real seeds")
        self.assertLess(hits, 40, "expected at least one evolve WITHOUT a key gate across 40 real seeds -- it should be a real fraction, not every time")

    def test_evolve_dungeon_sometimes_places_a_real_rune_gate_solvable_by_construction(self):
        """
        Real live feature (2026-09-04, Phase B port of rules/labyrinth.
        py's identical rune-gate mechanic, per Coffee: "have the mini
        boss, and boss and scatter them around, have it collected by
        battle and by chests" -- "if a gateway needs 3 the player will
        need 3 runes"). Statistical, same discipline as the key gate
        above: the door is a real add_rune_gate wiring, never shares a
        branch with the switch/plate/key gate, and the total number of
        guaranteed real rune sources (chest loot or guaranteed drop)
        always meets or exceeds the door's own required count, none of
        them sitting behind the gate itself or any other existing gate.
        """
        import copy
        hits = 0
        for seed in range(40):
            campaign = copy.deepcopy(bot.CAMPAIGN)
            rng = random.Random(seed)
            new_id = f"goblin_warrens_evolved_rune_stat_{seed}"
            dungeon_evolve.evolve_dungeon(campaign, "goblin_warrens", new_id, "underground", rebirth_gate=1, rng=rng)
            failures = dungeon_audit.audit_dungeon(campaign, new_id)
            for check_name, check_failures in failures.items():
                self.assertFalse(check_failures, f"seed {seed}, {check_name}: {check_failures}")
            rooms = dungeon_audit._dungeon_rooms(campaign, new_id)
            door = next((lk for r in rooms.values() for lk in r.get("lockables", []) if lk.get("requires_rune_item") == "labyrinth_rune"), None)
            if door is None:
                continue
            hits += 1
            needed = door["rune_count"]
            hub_id = next(rid for rid, r in rooms.items() if r.get("dungeon_hub"))
            gated_room_id = next(d for d, lid in rooms[hub_id]["locked_connections"].items() if lid == door["id"])
            rune_chest_rooms = [
                rid for rid, r in rooms.items() if any(lk.get("kind") == "chest" and "labyrinth_rune" in lk.get("loot", {}) for lk in r.get("lockables", []))
            ]
            rune_drop_rooms = [rid for rid, r in rooms.items() if r.get("guaranteed_rune_drop")]
            total_sources = len(rune_chest_rooms) + len(rune_drop_rooms)
            self.assertGreaterEqual(total_sources, needed, f"seed {seed}: door needs {needed} runes but only {total_sources} real sources were placed")
            locked_destinations = set(rooms[hub_id].get("locked_connections", {}).keys())
            for rid in rune_chest_rooms + rune_drop_rooms:
                self.assertNotEqual(rid, gated_room_id, "a rune source must never sit inside the very branch it gates")
                self.assertNotIn(rid, locked_destinations, "a rune source must sit in a plainly-reachable branch, not behind an unrelated existing gate")
            for rid in rune_drop_rooms:
                self.assertTrue(rooms[rid].get("monsters"), "a guaranteed rune drop must sit on a room with a real monster to defeat")
        self.assertGreater(hits, 0, "expected at least one rune-gated evolve across 40 real seeds")

    async def test_check_overworld_key_drop_grants_once_and_actually_persists_the_claim(self):
        """
        Real live bug found and fixed (2026-09-04) building the Locked
        Rune Doorway feature: campaign_loader.get_location returns a
        fresh copy, not the real dict living inside CAMPAIGN, so this
        function's old `location["key_drop_claimed"] = True` silently
        never persisted -- a repeat combat win at the same location
        would re-grant the key forever. Now fixed via
        bot._real_campaign_location; this guards the fix directly on
        the ORIGINAL sibling function (not just its new rune cousin).
        """
        import sessions
        loc_id = "key_drop_persistence_test_location"
        bot.CAMPAIGN["locations"]["underground"][loc_id] = {
            "name": "A Real Test Chamber", "connections": [], "guaranteed_key_drop": True,
        }
        try:
            user_id, chat_id = 962062, -962062
            make_basic_character(user_id, "OverworldKeyDropTester", chat_id=chat_id, current_location=loc_id)
            session = sessions.Session(chat_id=chat_id, participants=[], turn_order=[user_id], sides={user_id: "party"})
            before = (db.get_character(user_id, chat_id).get("inventory") or {}).get("labyrinth_floor_key", 0)
            sink = []
            await bot._check_overworld_key_drop(FakeUpdate(user_id, "", sink, chat_id=chat_id), session)
            after = db.get_character(user_id, chat_id).get("inventory", {}).get("labyrinth_floor_key", 0)
            self.assertEqual(after, before + 1, f"expected exactly one real key granted, got {sink}")
            self.assertTrue(bot.CAMPAIGN["locations"]["underground"][loc_id].get("key_drop_claimed"), "the claim must persist onto the real CAMPAIGN dict, not a throwaway copy")

            sink2 = []
            await bot._check_overworld_key_drop(FakeUpdate(user_id, "", sink2, chat_id=chat_id), session)
            after2 = db.get_character(user_id, chat_id).get("inventory", {}).get("labyrinth_floor_key", 0)
            self.assertEqual(after2, before + 1, "expected the guaranteed overworld key drop to be one-time only")
        finally:
            del bot.CAMPAIGN["locations"]["underground"][loc_id]

    async def test_mark_location_cleared_respects_a_real_repeated_gate(self):
        """
        Real "Advanced Dungeons" repeated gate, ported to evolved
        overworld dungeons (2026-09-06, per Coffee: "keep going" --
        a reference repeat-encounter dungeon's own real pattern, already shipped for the
        Labyrinth in v1.27.534). No monster-respawn logic needed here:
        an evolved-dungeon room's own `monsters` list is shared,
        campaign-wide state that's never cleared on a real victory in
        the first place, so this is purely a per-character defeat-count
        gate on WHEN cleared_locations actually fires.
        """
        import sessions
        loc_id = "repeat_gate_test_location"
        bot.CAMPAIGN["locations"]["underground"][loc_id] = {
            "name": "A Real Repeated Chamber", "connections": [], "is_miniboss_room": True, "repeat_required": 2,
        }
        try:
            user_id, chat_id = 962063, -962063
            make_basic_character(user_id, "RepeatGateOverworldTester", chat_id=chat_id, current_location=loc_id)
            session = sessions.Session(chat_id=chat_id, participants=[], turn_order=[user_id], sides={user_id: "party"})

            sink1 = []
            await bot._mark_location_cleared_for_party(FakeUpdate(user_id, "", sink1, chat_id=chat_id), session)
            character_after_1 = db.get_character(user_id, chat_id)
            self.assertNotIn(loc_id, character_after_1["cleared_locations"], "must not clear before the real requirement is met")
            self.assertEqual(character_after_1["location_defeat_counts"].get(loc_id), 1)
            self.assertTrue(any("flees deeper" in s for s in sink1), sink1)

            sink2 = []
            await bot._mark_location_cleared_for_party(FakeUpdate(user_id, "", sink2, chat_id=chat_id), session)
            character_after_2 = db.get_character(user_id, chat_id)
            self.assertIn(loc_id, character_after_2["cleared_locations"], "must clear on the real final defeat")
            self.assertFalse(any("flees deeper" in s for s in sink2), sink2)
        finally:
            del bot.CAMPAIGN["locations"]["underground"][loc_id]

