    async def test_run_is_shared_across_party_members(self):
        leader_id, follower_id, chat_id = 962003, 962004, -962003
        party_id = 88003
        make_basic_character(leader_id, "LabyrinthLeaderTester", chat_id=chat_id, current_location="the_colosseum")
        make_basic_character(follower_id, "LabyrinthFollowerTester", chat_id=chat_id, current_location="the_colosseum")
        db.update_character(leader_id, chat_id, defeated_monsters=["colosseum_champion"], party_id=party_id)
        db.update_character(follower_id, chat_id, party_id=party_id)

        await bot._do_enter_labyrinth(FakeUpdate(leader_id, "", [], chat_id=chat_id))
        follower_after_entry = db.get_character(follower_id, chat_id)
        self.assertEqual(follower_after_entry["current_location"], bot.LABYRINTH_LOCATION_SENTINEL)

        # Real branching topology (2026-09-03): the connector isn't
        # necessarily hub-adjacent anymore -- real BFS toward the
        # nearest descends_to room, walked one real hop at a time,
        # instead of assuming a single direct hub-to-stairs move.
        from collections import deque
        import sessions
        run = db.get_labyrinth_run(chat_id, f"party:{party_id}")
        # Real bounded loop (2026-09-06, real bug found and fixed: an
        # unbounded `while` here span forever at 100% CPU once a
        # gated miniboss/boss combat room -- a real live mechanic
        # since v1.27.505 -- could land on floor 1's main path. Every
        # `_do_labyrinth_move` into/through such a room is genuinely
        # refused until it's fought, so with no fight-it-first handling
        # (unlike `_walk_to_checkpoint` above, which already has this)
        # the loop just re-computed the identical BFS forever with zero
        # forward progress. Bounded the same way `_walk_to_checkpoint`
        # is, and now fights a gated room exactly the same way too.
        for _ in range(10 * labyrinth_module.SEGMENT_SIZE):
            if run["rooms"][run["current_room_id"]].get("descends_to"):
                break
            start = run["current_room_id"]
            start_room = run["rooms"][start]
            # Real live feature (2026-09-04): every floor now guarantees
            # a real mandatory gate on its own main path -- this test
            # isn't testing gating, same test-only auto-unlock shortcut
            # _walk_to_checkpoint above already uses (never a real
            # reward), branching by kind the same way bot._lockable_is_
            # open itself does (switch/pressure_plate/multi_switch_gate
            # check _SWITCH_STATE, everything else checks _UNLOCKED).
            for lockable_id in start_room.get("locked_connections", {}).values():
                lockable = next((lk for lk in start_room.get("lockables", []) if lk["id"] == lockable_id), None)
                if lockable is None:
                    continue
                if lockable.get("kind") == "multi_switch_gate":
                    switch_state = bot._chat_scoped_dict(bot._SWITCH_STATE, chat_id)
                    for req_id in lockable.get("requires", []):
                        switch_state[req_id] = True
                elif lockable.get("kind") in ("switch", "pressure_plate", "pillar"):
                    bot._chat_scoped_dict(bot._SWITCH_STATE, chat_id)[lockable_id] = True
                else:
                    bot._chat_scoped_set(bot._UNLOCKED, chat_id).add(lockable_id)
            # Same real mechanic, same test-only resolution as
            # `_walk_to_checkpoint` above: a gated miniboss/boss room
            # genuinely blocks moving onward until its monsters are
            # cleared -- fight it here before trying to continue.
            if bot._is_gated_combat_room(start_room):
                pre_gate_character = db.get_character(leader_id, chat_id)
                original_hp_current, original_hp_max = pre_gate_character["hp_current"], pre_gate_character["hp_max"]
                db.update_character(leader_id, chat_id, hp_current=999999, hp_max=999999)
                await bot._do_labyrinth_attack(FakeUpdate(leader_id, "attack", [], chat_id=chat_id), "attack")
                gate_session = sessions.get_session_for_user(chat_id, leader_id)
                if gate_session is not None:
                    for enemy in [p for p in gate_session.participants if gate_session.sides.get(p["telegram_user_id"]) == "enemy"]:
                        enemy["hp_current"] = 0
                    await bot._check_labyrinth_progress(FakeUpdate(leader_id, "", [], chat_id=chat_id), gate_session)
                    sessions.end_session(chat_id, gate_session)
                db.update_character(leader_id, chat_id, hp_current=original_hp_current, hp_max=original_hp_max)
                run = db.get_labyrinth_run(chat_id, f"party:{party_id}")
                continue
            came_from = {start: None}
            queue = deque([start])
            target_id = None
            while queue:
                cur = queue.popleft()
                if cur != start and run["rooms"][cur].get("descends_to"):
                    target_id = cur
                    break
                for nb in list(run["rooms"][cur].get("connections", [])) + list(run["rooms"][cur].get("locked_connections", {}).keys()):
                    if nb not in came_from and nb in run["rooms"]:
                        came_from[nb] = cur
                        queue.append(nb)
            self.assertIsNotNone(target_id, "no real path to a descends_to room")
            next_hop = target_id
            while came_from[next_hop] != start:
                next_hop = came_from[next_hop]
            target_name = run["rooms"][next_hop]["name"]
            await bot._do_labyrinth_move(FakeUpdate(leader_id, target_name, [], chat_id=chat_id), target_name)
            run = db.get_labyrinth_run(chat_id, f"party:{party_id}")
        await bot._do_labyrinth_move(FakeUpdate(leader_id, "go down", [], chat_id=chat_id), "go down")
        run_seen_by_leader = db.get_labyrinth_run(chat_id, f"party:{party_id}")
        run_seen_by_follower = db.get_labyrinth_run(chat_id, bot._labyrinth_party_key(follower_after_entry))
        self.assertEqual(run_seen_by_leader["current_room_id"], run_seen_by_follower["current_room_id"])
        self.assertEqual(run_seen_by_leader["floor"], 2)

