    async def test_find_lockable_resolves_by_distinctive_name_words_with_two_lockables_present(self):
        """
        Real live bug (2026-09-03, Coffee, dev-bridge: "Attack the
        crystal" -> a real "Success!" narration with no actual effect).
        Root cause: a real Labyrinth room ("Labyrinth -- A Sealed
        Archway") held BOTH a chest AND a switch at once -- the OLD
        "exactly one lockable in the room" fallback never fired with
        two present, and a generated lockable's real name ("a distant
        necrotic crystal, humming faintly") is far too flavorful to
        ever literally appear in a player's own phrasing, so _find_
        lockable returned None and _do_skill_check silently ran a
        meaningless generic ability check instead of the real switch.
        _find_lockable now matches each lockable's own DISTINCTIVE name
        words first (skipping short/common ones) before falling back to
        generic kind-words, which can genuinely tie between two
        different lockables ("lock" matches both a chest and a switch).
        """
        room = {
            "lockables": [
                {"id": "f1_gate_cache", "kind": "chest", "name": "a real cache behind the archway", "loot": {}, "gold": 74},
                {"id": "seg1_switch_0", "kind": "switch", "name": "a distant necrotic crystal, humming faintly", "element": "necrotic"},
            ]
        }
        self.assertEqual(bot._find_lockable(room, "Attack the crystal")["id"], "seg1_switch_0")
        self.assertEqual(bot._find_lockable(room, "Cast fireball onto the crystal")["id"], "seg1_switch_0")
        self.assertEqual(bot._find_lockable(room, "open the cache")["id"], "f1_gate_cache")
        self.assertEqual(bot._find_lockable(room, "loot the cache")["id"], "f1_gate_cache")
        # Real live bug found and fixed (2026-09-04, Coffee, dev-bridge:
        # "Picking the lock didn't work for some reason the cache is
        # still there and I didn't get the item" -- this exact room
        # shape): "lock" used to live in EVERY kind's word list
        # (switch/lever/pressure_plate included), so "Pick the lock"
        # matched both the chest AND the switch here and this correctly
        # refused to guess -- but a switch/crystal isn't a real lock in
        # any literal sense, so the refusal itself was the bug. "lock"
        # now lives only on chest/door (an actual, literal lock);
        # "Pick the lock" here unambiguously means the real cache.
        self.assertEqual(bot._find_lockable(room, "Pick the lock")["id"], "f1_gate_cache")

    async def test_find_lockable_resolves_a_plain_crystal_whose_name_is_a_subset_of_another(self):
        """
        Real live bug (2026-09-10, dev-bridge screenshot, Coffee: "It
        doesn't seem to recognize that we're actually typing the proper
        crystal's name") -- a real Labyrinth room (Floor 10, "A Room
        That Shouldn't Fit 1") held both a plain "a physical crystal"
        (f10_branchswitch, the real branch-opening switch the player
        needed) and "a shuddering physical crystal" (f10_collapse_
        switch, an unrelated collapse-puzzle trigger), both rolling the
        SAME element by chance. The plain crystal's entire name is a
        strict subset of the shuddering one's, so it had zero words of
        its own the distinctive-word check could ever key on -- every
        natural phrase for it ("hit the physical crystal", "hit the
        plain physical crystal") fell through as merely ambiguous, with
        no phrasing that could ever single it out. Confirmed against
        the exact real room data pulled from the live labyrinth_runs
        row before this fix (id f10_r0, seed 1229253006).
        """
        room = {
            "lockables": [
                {"id": "f10_branchswitch", "kind": "switch", "name": "a physical crystal", "element": "physical"},
                {"id": "f10_collapse_switch", "kind": "switch", "name": "a shuddering physical crystal", "element": "physical"},
            ]
        }
        self.assertEqual(bot._find_lockable(room, "Hit the physical crystal")["id"], "f10_branchswitch")
        self.assertEqual(bot._find_lockable(room, "Hit physical crystal")["id"], "f10_branchswitch")
        self.assertEqual(bot._find_lockable(room, "strike the plain physical crystal")["id"], "f10_branchswitch")
        self.assertEqual(bot._find_lockable(room, "hit the shuddering crystal")["id"], "f10_collapse_switch")
        self.assertEqual(bot._find_lockable(room, "hit the shuddering physical crystal")["id"], "f10_collapse_switch")
        # Regression guard: two IDENTICALLY-named switches (the earlier
        # 2026-09-05 "two unlabeled necrotic crystals" bug) must still
        # correctly refuse to guess -- neither is a proper subset of
        # the other, so this new check must never fire for them.
        identical_room = {
            "lockables": [
                {"id": "necA", "kind": "switch", "name": "a necrotic crystal", "element": "necrotic"},
                {"id": "necB", "kind": "switch", "name": "a necrotic crystal", "element": "necrotic"},
            ]
        }
        self.assertIsNone(bot._find_lockable(identical_room, "hit the necrotic crystal"))

    async def test_find_lockable_disambiguates_the_mandatory_and_optional_key_gate_doors(self):
        """
        Real live bug found and fixed (2026-09-05, exposed by an RNG-
        stream shift from an unrelated loot change elsewhere in
        generate_floor): the mandatory main-path key gate and the
        separate optional key gate used to share the EXACT literal
        name "a real, heavily-barred door" -- harmless while they could
        never coexist, but a real _find_lockable ambiguity the moment
        both fired on the same floor (an always-possible, independent-
        rolls scenario, not actually rare by construction). Each now
        has its own distinct name; a specific "main"/"side" phrasing
        must resolve unambiguously, and a genuinely generic "the barred
        door" must still honestly refuse rather than guess wrong.
        """
        room = {
            "lockables": [
                {"id": "f1_maingate", "kind": "door", "name": "a real, heavily-barred main door", "requires_key_item": "labyrinth_floor_key"},
                {"id": "f1_key_gate", "kind": "door", "name": "a real, heavily-barred side door", "requires_key_item": "labyrinth_floor_key"},
            ]
        }
        self.assertEqual(bot._find_lockable(room, "open the main door")["id"], "f1_maingate")
        self.assertEqual(bot._find_lockable(room, "open the side door")["id"], "f1_key_gate")
        self.assertIsNone(bot._find_lockable(room, "open the barred door"), "a genuinely ambiguous phrase must still refuse to guess, never pick one silently")

    async def test_cast_fire_spell_onto_a_labyrinth_switch_actually_activates_it(self):
        """
        Real live bug (2026-09-02, Coffee, dev-bridge: "Cast fireball
        onto the crystal" -> "There's nothing to cast that at right
        now"). _do_cast_spell's non-combat object-targeting branch had
        the same CAMPAIGN-only location bug as _do_skill_check/
        _do_lockpick -- now uses _location_or_labyrinth_room too.
        """
        user_id, chat_id = 962040, -962040
        make_basic_character(
            user_id, "LabyrinthCastSwitchTester", chat_id=chat_id, current_location="the_colosseum", char_class="Wizard",
        )
        db.update_character(
            user_id, chat_id, defeated_monsters=["colosseum_champion"],
            known_spells=["fireball"], spell_slots_current=2, spell_slots_max=2,
        )
        await bot._do_enter_labyrinth(FakeUpdate(user_id, "", [], chat_id=chat_id))
        party_key = f"solo:{user_id}"
        run = db.get_labyrinth_run(chat_id, party_key)
        hub = run["rooms"][run["current_room_id"]]
        # Real generation can randomly place its own lockable in the hub
        # too (e.g. the L2e multi-switch puzzle) -- reset to exactly one
        # so _find_lockable's single-lockable fallback is deterministic.
        hub["lockables"] = [{"id": "test_crystal2", "kind": "switch", "name": "a fire crystal", "element": "fire"}]
        db.update_labyrinth_run(chat_id, party_key, rooms=run["rooms"])

        sink = []
        await bot._dispatch_intent(
            FakeUpdate(user_id, "Cast fireball onto the crystal", sink, chat_id=chat_id), DummyContext(),
            {"action": "cast_spell", "raw_text": "Cast fireball onto the crystal"}, "Cast fireball onto the crystal",
        )
        self.assertFalse(any("nothing to cast that at" in s for s in sink))
        self.assertTrue(any("flares to life" in s for s in sink), f"expected the switch to actually activate, got: {sink}")
        character_after = db.get_character(user_id, chat_id)
        self.assertEqual(character_after["spell_slots_current"], 1, "a real spell slot must have been spent")

