    def test_generate_floor_warps_never_connect_two_already_adjacent_branches(self):
        """
        Real live bug found and fixed (2026-09-04, Coffee, dev-bridge:
        "I don't understand what the point of this warp was because we
        were already able to access this room. The point of warps are
        to bring us to an area of the dungeon that we weren't able to
        get to before"): a warp used to connect two branch ROOTS (each
        only one hop from the hub), which never actually saved any real
        distance. Statistical, BFS-verified: every generated warp must
        connect two rooms whose real graph distance (ignoring the warp
        itself) is genuinely greater than what the warp provides (1
        hop) -- i.e. always a real shortcut, never a no-op.
        """
        from collections import deque

        def bfs_distance(rooms, start, end):
            visited = {start: 0}
            queue = deque([start])
            while queue:
                cur = queue.popleft()
                neighbors = list(rooms[cur].get("connections", [])) + list(rooms[cur].get("locked_connections", {}).keys())
                for nb in neighbors:
                    if nb not in visited and nb in rooms:
                        visited[nb] = visited[cur] + 1
                        queue.append(nb)
            return visited.get(end)

        checked = 0
        for seed in range(500):
            floor_data = labyrinth_module.generate_floor(bot.CAMPAIGN, 3, random.Random(seed))
            rooms = floor_data["rooms"]
            seen_pairs = set()
            for rid, r in rooms.items():
                for warp_target in r.get("warps", []):
                    pair = tuple(sorted((rid, warp_target)))
                    if pair in seen_pairs:
                        continue
                    seen_pairs.add(pair)
                    checked += 1
                    dist = bfs_distance(rooms, pair[0], pair[1])
                    self.assertIsNotNone(dist, f"seed {seed}: warp pair {pair} must still be reachable via the plain graph")
                    self.assertGreaterEqual(dist, 4, f"seed {seed}: warp pair {pair} only {dist} hops apart the long way -- not a real shortcut")
        self.assertGreater(checked, 0, "expected at least one real warp across 500 real seeds")

    async def test_labyrinth_key_gate_end_to_end_chest_and_drop_and_consumption(self):
        """Real end-to-end: find/obtain the key (via the real chest-loot path or a real combat victory), open the real gated door with it, and confirm the key is gone afterward -- not just comparing generator output in isolation."""
        async def _walk_to_room(rooms, start_id, target_id, user_id, chat_id):
            # Real fix (2026-09-05, alongside "longer interconnectable
            # pathways"): a single _do_labyrinth_move call only ever
            # covers ONE hop -- fine when every branch topped out at 2
            # extra rooms, but the widened _BRANCH_DEPTH_WEIGHTS above
            # can now genuinely put the key chest/drop room several real
            # hops deep, so a direct move silently failed to reach it.
            # Real BFS walk over the floor's own `connections`, one real
            # _do_labyrinth_move per hop, same discipline this file's
            # own _walk_to_checkpoint helper already uses elsewhere.
            from collections import deque
            parent = {start_id: None}
            queue = deque([start_id])
            while queue:
                cur = queue.popleft()
                if cur == target_id:
                    break
                for nb in rooms[cur].get("connections", []):
                    if nb in rooms and nb not in parent:
                        parent[nb] = cur
                        queue.append(nb)
            path = []
            node = target_id
            while node is not None:
                path.append(node)
                node = parent.get(node)
            path.reverse()
            for room_id in path[1:]:
                await bot._do_labyrinth_move(FakeUpdate(user_id, "", [], chat_id=chat_id), rooms[room_id]["name"])

        user_id, chat_id = 962060, -962060
        party_key = f"solo:{user_id}"
        make_basic_character(user_id, "KeyGateTester", chat_id=chat_id, current_location=bot.LABYRINTH_LOCATION_SENTINEL, hp_max=999999)
        db.update_character(user_id, chat_id, defeated_monsters=["colosseum_champion"], hp_current=999999)
        db.add_item(user_id, chat_id, "torch", 1)  # a real light source -- a "lightless" floor modifier must never block interacting with the real key gate/chest/monster this test exercises
        found_chest_case = found_drop_case = False
        for seed in range(100):
            if found_chest_case and found_drop_case:
                break
            floor_data = labyrinth_module.generate_floor(bot.CAMPAIGN, 1, random.Random(seed))
            rooms = floor_data["rooms"]
            hub_id = floor_data["hub_room_id"]
            hub = rooms[hub_id]
            key_doors = [lk for lk in hub.get("lockables", []) if lk.get("requires_key_item") == "labyrinth_floor_key"]
            # Real, rare edge case (2026-09-05): the mandatory main-path
            # gate and the separate optional key gate are independent
            # rolls -- both CAN choose "key" on the same floor. Each now
            # gets its own real, distinct name ("...main door" vs
            # "...side door", a genuine, separate fix), but "open the
            # barred door" below is deliberately generic text this test
            # uses to exercise ONE specific gate end-to-end -- skip a
            # seed where both fired, that dual-gate scenario deserves
            # its own dedicated test, not a silent `next()` pick here.
            if len(key_doors) != 1:
                continue
            door = key_doors[0]
            gated_room_id = next(d for d, lid in hub["locked_connections"].items() if lid == door["id"])
            # Real fix (2026-09-05, alongside "longer interconnectable
            # pathways"): more mechanics can now genuinely compete for
            # the same floor's `other_chains` (mandatory gate, optional
            # branch gate, rune/switch gates, shortcut levers, carry
            # puzzles), so the key chest/drop room this test cares about
            # can itself land behind a DIFFERENT, unrelated gate this
            # test was never meant to also solve. Only real plain-
            # connections-reachable candidates count -- this test is
            # about the key gate mechanic specifically, not chained
            # multi-gate solving.
            from collections import deque
            plain_reachable = {hub_id}
            _frontier = deque([hub_id])
            while _frontier:
                _cur = _frontier.popleft()
                for _nb in rooms[_cur].get("connections", []):
                    if _nb in rooms and _nb not in plain_reachable:
                        plain_reachable.add(_nb)
                        _frontier.append(_nb)
            key_chest_room = next(
                (rid for rid, r in rooms.items()
                 if rid in plain_reachable
                 and any(lk.get("kind") == "chest" and "labyrinth_floor_key" in lk.get("loot", {}) for lk in r.get("lockables", []))),
                None,
            )
            key_drop_room = next(
                (rid for rid, r in rooms.items() if rid in plain_reachable and r.get("guaranteed_key_drop")), None,
            )
            is_chest_case = key_chest_room is not None and not found_chest_case
            is_drop_case = key_drop_room is not None and not found_drop_case and not is_chest_case
            if not is_chest_case and not is_drop_case:
                continue
            import sessions
            # Each loop iteration simulates an independent, fresh floor-1
            # playthrough sharing one chat_id -- real _do_enter_labyrinth
            # resets this same state on a genuine new run (see
            # bot._reset_labyrinth_lockable_state's own docstring for the
            # real bug this guards against), so the direct-DB-create
            # shortcut here must match that or a later seed's own
            # identically-named "f1_key_gate" door falsely inherits an
            # earlier seed's "already unlocked" state within this test.
            bot._reset_labyrinth_lockable_state(chat_id)
            db.create_labyrinth_run(chat_id, party_key, floor=1, seed=seed, current_room_id=hub_id, rooms=rooms)
            if is_chest_case:
                found_chest_case = True
                lockable_id = next(lk["id"] for lk in rooms[key_chest_room]["lockables"] if lk.get("kind") == "chest" and "labyrinth_floor_key" in lk.get("loot", {}))
                await _walk_to_room(rooms, hub_id, key_chest_room, user_id, chat_id)
                await bot._do_skill_check(FakeUpdate(user_id, "open the lockbox", [], chat_id=chat_id), "dexterity", "open the lockbox", forced_roll=20)
            else:
                found_drop_case = True
                await _walk_to_room(rooms, hub_id, key_drop_room, user_id, chat_id)
                await bot._do_labyrinth_attack(FakeUpdate(user_id, "attack", [], chat_id=chat_id), "attack")
                fight_session = sessions.get_session_for_user(chat_id, user_id)
                if fight_session is not None:
                    for enemy in [p for p in fight_session.participants if fight_session.sides.get(p["telegram_user_id"]) == "enemy"]:
                        enemy["hp_current"] = 0
                    await bot._check_labyrinth_progress(FakeUpdate(user_id, "", [], chat_id=chat_id), fight_session)
                    sessions.end_session(chat_id, fight_session)
            character = db.get_character(user_id, chat_id)
            self.assertIn("labyrinth_floor_key", character["inventory"], "expected the key to actually be obtained")

            current_room_id = db.get_labyrinth_run(chat_id, party_key)["current_room_id"]
            await _walk_to_room(rooms, current_room_id, hub_id, user_id, chat_id)
            sink = []
            await bot._do_skill_check(FakeUpdate(user_id, "open the barred door", sink, chat_id=chat_id), "dexterity", "open the barred door")
            self.assertTrue(any("opens" in s for s in sink), sink)
            character_after = db.get_character(user_id, chat_id)
            self.assertNotIn("labyrinth_floor_key", character_after["inventory"], "the key must be consumed on use")

            await bot._do_labyrinth_move(FakeUpdate(user_id, "", [], chat_id=chat_id), rooms[gated_room_id]["name"])
            self.assertEqual(db.get_labyrinth_run(chat_id, party_key)["current_room_id"], gated_room_id)
            db.delete_labyrinth_run(chat_id, party_key)
        self.assertTrue(found_chest_case, "expected at least one chest-style key case across 100 real seeds")
        self.assertTrue(found_drop_case, "expected at least one drop-style key case across 100 real seeds")

