    def test_generate_floor_places_a_real_carry_puzzle_solvable_by_construction(self):
        """
        Real, more literal the reference tower dungeon mechanic (2026-09-03, per
        Coffee's own live screenshot re-ask: "multiple levels floors
        and basements to get to the other end of the dungeon"), a real
        object carried between rooms and struck against 2 scattered
        pillars. Statistical: when it fires, the object always starts
        in the hub (never behind content a player hasn't reached), both
        pillars live outside the branch being sealed, and it's never
        placed on the same floor as the simpler single-switch collapse
        puzzle (mutually exclusive by design).
        """
        carry_seen = False
        for seed in range(150):
            floor_data = labyrinth_module.generate_floor(bot.CAMPAIGN, 20, random.Random(seed))
            rooms = floor_data["rooms"]
            hub = rooms[floor_data["hub_room_id"]]
            carry_lk = next((lk for lk in hub.get("lockables", []) if lk.get("kind") == "carry_object"), None)
            if carry_lk is None:
                continue
            carry_seen = True
            puzzle_id = carry_lk["puzzle_id"]
            pillar_rooms = [
                (rid, lk) for rid, r in rooms.items() for lk in r.get("lockables", [])
                if lk.get("kind") == "pillar" and lk.get("puzzle_id") == puzzle_id
            ]
            self.assertEqual(len(pillar_rooms), 2, "expected exactly 2 real pillars for this puzzle")
            pillar_ids = [lk["id"] for _, lk in pillar_rooms]

            trigger_room = next(r for r in rooms.values() if r.get("collapsing_connections"))
            seal_leaf, trigger_id = next(iter(trigger_room["collapsing_connections"].items()))
            trigger_lockable = next(lk for lk in trigger_room["lockables"] if lk["id"] == trigger_id)
            self.assertEqual(set(trigger_lockable["requires"]), set(pillar_ids))

            for pillar_room_id, _ in pillar_rooms:
                self.assertNotEqual(pillar_room_id, seal_leaf, "a pillar must never live inside the branch it seals")

            # Never coexists with the simpler single-switch collapse trigger on the same floor.
            collapse_triggers = [
                lk for r in rooms.values() for lk in r.get("lockables", [])
                if lk.get("kind") == "multi_switch_gate" and lk["id"].endswith("_collapse_trigger")
            ]
            self.assertEqual(collapse_triggers, [], "the carry puzzle and the simpler collapse puzzle must be mutually exclusive")
            break
        self.assertTrue(carry_seen, "expected at least one real carry puzzle across 150 real seeds")

    def test_generate_floor_hint_statue_only_appears_with_something_real_to_hint_at(self):
        """
        Real owl-statue-style hint (2026-09-03, classic action-adventure
        research). Statistical: a hint statue only ever appears in the
        hub when the floor genuinely has a miniboss/gate/collapse/warp
        to hint at, and its real hint_lines never name a room or exact
        position (feedback_never_spoil_puzzle_answers).

        Real live change (2026-09-04, mandatory main-path gating, per
        Coffee: "we should not be able to walk from one floor to the
        next... it should feel like a maze or a labyrinth"): every
        floor now guarantees a real `locked_connections` entry (the new
        mandatory gate), so "a floor with nothing real to hint at" no
        longer exists at all -- the complementary "no_statue_seen" half
        of this test's original claim is now structurally impossible
        and has been dropped; the still-real, still-important half
        (a statue never appears with NOTHING real behind it) is
        unaffected and stays.
        """
        statue_seen = False
        for seed in range(80):
            floor_data = labyrinth_module.generate_floor(bot.CAMPAIGN, 20, random.Random(seed))
            rooms = floor_data["rooms"]
            hub = rooms[floor_data["hub_room_id"]]
            statue = next((lk for lk in hub.get("lockables", []) if lk.get("kind") == "hint_statue"), None)
            has_real_feature = (
                any(r.get("is_miniboss_room") for r in rooms.values())
                or any(r.get("locked_connections") for r in rooms.values())
                or any(r.get("collapsing_connections") for r in rooms.values())
                or any(r.get("warps") for r in rooms.values())
                or any(r.get("is_gated_encounter") for r in rooms.values())
            )
            if statue is not None:
                statue_seen = True
                self.assertTrue(has_real_feature, "a statue must never appear with nothing real to hint at")
                self.assertTrue(statue["hint_lines"], "expected at least one real hint line")
                for line in statue["hint_lines"]:
                    for rid, r in rooms.items():
                        self.assertNotIn(r["name"], line, f"hint line spoils a real room name: {line!r}")
        self.assertTrue(statue_seen, "expected at least one real hint statue across 80 real seeds")

    async def test_pick_the_lock_opens_the_real_chest_not_a_coexisting_switch_end_to_end(self):
        """
        Real live bug found and fixed (2026-09-04, Coffee, dev-bridge:
        "Picking the lock didn't work for some reason the cache is
        still there and I didn't get the item" -- a real room holding
        both a locked chest and an elemental switch): "lock" used to
        live in every kind's word list, so "Pick the lock" matched both
        the chest and the switch, _find_lockable correctly refused to
        guess, and the whole action silently fell through to a generic,
        ungrounded ability check that narrated a fake success while the
        chest stayed locked and no item was ever granted. Full
        _do_skill_check dispatch, not just _find_lockable in isolation
        -- confirms the real chest actually opens and the real loot
        actually lands in the party's stash.
        """
        user_id, chat_id = 962071, -962071
        make_basic_character(user_id, "PickLockChestTester", chat_id=chat_id, current_location="the_colosseum")
        db.update_character(user_id, chat_id, defeated_monsters=["colosseum_champion"])
        await bot._do_enter_labyrinth(FakeUpdate(user_id, "", [], chat_id=chat_id))
        party_key = f"solo:{user_id}"
        run = db.get_labyrinth_run(chat_id, party_key)
        hub = run["rooms"][run["current_room_id"]]
        hub["lockables"] = [
            {"id": "test_cache", "kind": "chest", "name": "a real, hastily-buried cache", "loot": {"healing_potion": 1}, "gold": 20},
            {"id": "test_crystal", "kind": "switch", "name": "a shuddering lightning crystal", "element": "lightning"},
        ]
        db.update_labyrinth_run(chat_id, party_key, rooms=run["rooms"])
        character = db.get_character(user_id, chat_id)
        before_potions = character["inventory"].get("healing_potion", 0)

        sink = []
        await bot._do_skill_check(FakeUpdate(user_id, "Pick the lock", sink, chat_id=chat_id), "dexterity", "Pick the lock", forced_roll=20)
        self.assertIn("test_cache", bot._UNLOCKED.get(chat_id, set()), f"expected the real chest to actually unlock, got: {sink}")
        self.assertNotIn("test_crystal", bot._chat_scoped_dict(bot._SWITCH_STATE, chat_id), "the coexisting switch must never be toggled by this")
        character_after = db.get_character(user_id, chat_id)
        self.assertEqual(character_after["inventory"].get("healing_potion", 0), before_potions + 1, f"expected the real loot to actually be granted, got: {sink}")

