    def test_labyrinth_locked_door_color_matches_its_gating_switchs_element(self):
        """
        Real live request (2026-09-03, Coffee, dev-bridge screenshot:
        "switches and doors that are controlled by a certain element...
        some kind of label colour or indication that is connected to
        that crystal switch or lever"). A door gated by an elemental
        switch (branch gate, collapse trigger) must draw in that
        element's own color, matching the switch dot's already-shipped
        color-coding.

        Extended 2026-09-05 (per Coffee's own "Advanced Dungeon Map
        System" research): key/rune/pressure-plate gates now each get
        their own real, distinct color too -- only a plain DC13 door
        with genuinely nothing to color-code to (no element, no key,
        no rune, not a plate) falls back to the flat generic gold.
        """
        import map_render
        rooms = {
            "hub": {"id": "hub", "lockables": [
                {"id": "gate1", "kind": "multi_switch_gate", "requires": ["sw1"]},
            ], "locked_connections": {"gated_room": "gate1"}},
            "sw_room": {"id": "sw_room", "lockables": [{"id": "sw1", "kind": "switch", "element": "fire"}]},
            "gated_room": {"id": "gated_room"},
            "plate_room": {"id": "plate_room", "lockables": [
                {"id": "plate1", "kind": "pressure_plate"},
            ], "locked_connections": {"plate_gated_room": "plate1"}},
            "plate_gated_room": {"id": "plate_gated_room"},
            "key_room": {"id": "key_room", "lockables": [
                {"id": "key1", "kind": "door", "requires_key_item": "the_test_key"},
            ], "locked_connections": {"key_gated_room": "key1"}},
            "key_gated_room": {"id": "key_gated_room"},
            "rune_room": {"id": "rune_room", "lockables": [
                {"id": "rune1", "kind": "door", "requires_rune_item": "labyrinth_rune", "rune_count": 3},
            ], "locked_connections": {"rune_gated_room": "rune1"}},
            "rune_gated_room": {"id": "rune_gated_room"},
            "plain_room": {"id": "plain_room", "lockables": [
                {"id": "plain1", "kind": "door"},
            ], "locked_connections": {"no_element_room": "plain1"}},
            "no_element_room": {"id": "no_element_room"},
        }
        self.assertEqual(
            map_render._labyrinth_locked_door_color("hub", "gated_room", rooms),
            map_render._SWITCH_ELEMENT_COLORS["fire"],
        )
        self.assertEqual(
            map_render._labyrinth_locked_door_color("plate_room", "plate_gated_room", rooms),
            map_render._LABYRINTH_ICON_COLORS["pressure_plate"],
        )
        self.assertEqual(
            map_render._labyrinth_locked_door_color("key_room", "key_gated_room", rooms),
            map_render._KEY_GATE_COLOR,
        )
        self.assertEqual(
            map_render._labyrinth_locked_door_color("rune_room", "rune_gated_room", rooms),
            map_render._RUNE_GATE_COLOR,
        )
        self.assertEqual(
            map_render._labyrinth_locked_door_color("plain_room", "no_element_room", rooms),
            map_render._LOCKED_DOOR_COLOR,
        )

    def test_labyrinth_map_icons_cover_pressure_plate_carry_object_pillar_and_hint_statue(self):
        """
        Real gap found (2026-09-03, Coffee: "did you miss anything on
        the generator?"): pressure plates (v1.27.488), carry objects/
        pillars (v1.27.489), and the hint statue (v1.27.490) all got
        real text descriptions via _lockable_callout_lines, but were
        never added to _labyrinth_room_icons -- a room holding one of
        these drew with NO icon at all on the actual map image. A
        pillar's own dot also reflects its real struck/unstruck state,
        same as a switch.
        """
        import map_render
        room = {
            "id": "r1",
            "lockables": [
                {"id": "plate1", "kind": "pressure_plate"},
                {"id": "carry1", "kind": "carry_object", "puzzle_id": "p1"},
                {"id": "pillar1", "kind": "pillar", "puzzle_id": "p1"},
                {"id": "statue1", "kind": "hint_statue", "hint_lines": ["A real fact."]},
            ],
        }
        icons = map_render._labyrinth_room_icons(room, switch_states={})
        categories = [c for c, _ in icons]
        self.assertIn("pressure_plate", categories)
        self.assertIn("carry_object", categories)
        self.assertIn("pillar", categories)
        self.assertIn("hint_statue", categories)

        # A struck pillar's dot color changes, same convention as a switch.
        unstruck_color = dict(icons)["pillar"]
        struck_icons = map_render._labyrinth_room_icons(room, switch_states={"pillar1": True})
        struck_color = dict(struck_icons)["pillar"]
        self.assertNotEqual(unstruck_color, struck_color)

        # And the map actually renders without crashing, with a real legend line for each.
        from unittest.mock import patch
        rooms = {"r1": {**room, "grid_position": {"x": 0, "y": 0}, "name": "Test Room", "connections": []}}
        with patch("map_render._fetch_labyrinth_room_tile", return_value=None):
            png_bytes = map_render.render_labyrinth_map(1, rooms, "r1", set(), set(rooms.keys()), {}, None)
        self.assertGreater(len(png_bytes), 0)

