    async def test_labyrinth_hazard_and_entry_never_touch_benched_inactive_or_a_dormant_alt(self):
        """
        Real live bug (2026-09-03, Coffee, dev-bridge screenshot: a
        single Labyrinth trap rolled saves for and damaged 12 characters
        at once -- "The trap shouldn't be hurting people that aren't in
        the active party and it shouldn't definitely be hurting inactive
        members"). Root cause: every Labyrinth "whole party" handler
        (enter/leave, checkpoint heals, hazard saves, best-floor
        tracking, shrine offerings) called the raw db.get_party_members_
        by_id directly, with none of the exclusions _get_real_party_
        combatants already established for ordinary combat back on
        2026-08-13 -- a real live bug where a single human's own dormant
        ALT character (Laurienna/Charvenna, Ravenloft/Pan -- the exact
        names that showed up again in this new screenshot) got double-
        counted as a second party member, and benched/resting members
        were swept in unasked. Fixed via one shared _labyrinth_active_
        party_members helper, reused everywhere. This test proves the
        two real vectors from the live screenshot directly: a benched/
        resting member and a dormant alt must never be moved into the
        Labyrinth OR take real hazard damage.
        """
        from unittest.mock import patch
        leader_id, chat_id = 962033, -962033
        make_basic_character(leader_id, "LabyrinthPartyScopeLeader", chat_id=chat_id, current_location="the_colosseum", hp_max=200)
        db.update_character(leader_id, chat_id, defeated_monsters=["colosseum_champion"], hp_current=200, dexterity=8)
        party_id = db.create_party(leader_id, chat_id)

        benched_id = 962034
        make_basic_character(benched_id, "BenchedMember", chat_id=chat_id, current_location="crossroads_tavern", hp_max=100)
        db.update_character(benched_id, chat_id, party_id=party_id, is_benched=1, hp_current=100, dexterity=8)

        resting_id = 962035
        make_basic_character(resting_id, "RestingMember", chat_id=chat_id, current_location="crossroads_tavern", hp_max=100)
        db.update_character(resting_id, chat_id, party_id=party_id, is_inactive=1, hp_current=100, dexterity=8)

        # A dormant alt: the SAME owner as a real active member, but a
        # newer character db.create_character makes the active one --
        # the exact Laurienna/Charvenna shape from the live incident.
        alt_owner_id = 962036
        alt_old = make_basic_character(alt_owner_id, "AltOld", chat_id=chat_id, current_location="crossroads_tavern", hp_max=100)
        db.update_character_by_id(alt_old["character_id"], party_id=party_id, hp_current=100, dexterity=8)
        alt_new = db.create_character(
            telegram_user_id=alt_owner_id, chat_id=chat_id, name="AltNew", race="Human", char_class="Fighter",
            ability_scores={"strength": 10, "dexterity": 8, "constitution": 10, "intelligence": 10, "wisdom": 10, "charisma": 10},
            hp_max=100, armor_class=11, gold=0, inventory={}, known_spells=[], current_location="the_colosseum",
        )
        db.update_character_by_id(alt_new["character_id"], party_id=party_id, hp_current=100)

        await bot._do_enter_labyrinth(FakeUpdate(leader_id, "", [], chat_id=chat_id))

        # Entry must never relocate a benched/resting member or a dormant alt.
        self.assertEqual(db.get_character(benched_id, chat_id)["current_location"], "crossroads_tavern")
        self.assertEqual(db.get_character(resting_id, chat_id)["current_location"], "crossroads_tavern")
        self.assertEqual(db.get_character_by_id(alt_old["character_id"])["current_location"], "crossroads_tavern")
        # The real active alt (AltNew) DOES travel with the party.
        self.assertEqual(db.get_character(alt_owner_id, chat_id)["current_location"], bot.LABYRINTH_LOCATION_SENTINEL)

        party_key = f"party:{party_id}"
        run = db.get_labyrinth_run(chat_id, party_key)
        rooms = run["rooms"]
        # Same real fix as the hazard test above -- the hub's own
        # `connections` list is exactly the set of plain, already-
        # unlocked, one-hop-reachable rooms on the current floor.
        hazard_room_id = rooms[run["current_room_id"]]["connections"][0]
        rooms[hazard_room_id]["hazard"] = "fire"
        db.update_labyrinth_run(chat_id, party_key, rooms=rooms)
        hazard_room_name = rooms[hazard_room_id]["name"]

        with patch("bot.roll_d20", return_value=1):
            sink = []
            await bot._do_labyrinth_move(FakeUpdate(leader_id, "", sink, chat_id=chat_id), f"go to {hazard_room_name}")

        combined = "\n".join(sink)
        self.assertNotIn("BenchedMember", combined)
        self.assertNotIn("RestingMember", combined)
        self.assertNotIn("AltOld", combined)
        # Untouched HP -- the real proof no damage was silently applied.
        self.assertEqual(db.get_character(benched_id, chat_id)["hp_current"], 100)
        self.assertEqual(db.get_character(resting_id, chat_id)["hp_current"], 100)
        self.assertEqual(db.get_character_by_id(alt_old["character_id"])["hp_current"], 100)

    async def test_labyrinth_leave_resets_a_party_member_even_after_the_owner_switches_active_alt(self):
        """
        Real live bug (2026-09-03, found investigating a real "stuck in
        the Labyrinth" report -- Coffee's own character "Ravenloft" was
        left at LABYRINTH_LOCATION_SENTINEL with no matching run after
        issuing "leave the labyrinth"). Root cause: Ravenloft entered
        the Labyrinth while active, then the SAME owner switched their
        globally active character to a different alt ("Elduinn," same
        party) without leaving first. Leaving as Elduinn correctly
        found and deleted the real party-shared run (party_key is
        party-scoped, not tied to whichever character issued the
        command) -- but _labyrinth_active_party_members's old "must be
        the globally active character" exclusion then wrongly skipped
        resetting RAVENLOFT's own current_location, since he was no
        longer the active alt, even though he was demonstrably still
        sitting at the sentinel. Fixed: a member now also counts as
        active if their OWN current_location genuinely is the sentinel,
        not just "are they the globally active character right now."
        """
        owner_id, chat_id = 962037, -962037
        first = make_basic_character(owner_id, "RavenloftTester", chat_id=chat_id, current_location="the_colosseum")
        db.update_character_by_id(first["character_id"], defeated_monsters=["colosseum_champion"])
        party_id = db.create_party(owner_id, chat_id)
        db.update_character_by_id(first["character_id"], party_id=party_id)
        db.switch_character(owner_id, chat_id, first["character_id"])

        await bot._do_enter_labyrinth(FakeUpdate(owner_id, "", [], chat_id=chat_id))
        self.assertEqual(db.get_character_by_id(first["character_id"])["current_location"], bot.LABYRINTH_LOCATION_SENTINEL)

        # The SAME owner switches to a different alt, same party --
        # never having left the Labyrinth with the first character.
        second = db.create_character(
            telegram_user_id=owner_id, chat_id=chat_id, name="ElduinnTester", race="Human", char_class="Fighter",
            ability_scores={"strength": 10, "dexterity": 10, "constitution": 10, "intelligence": 10, "wisdom": 10, "charisma": 10},
            hp_max=20, armor_class=11, gold=0, inventory={}, known_spells=[], current_location="crossroads_tavern",
        )
        db.update_character_by_id(second["character_id"], party_id=party_id)
        db.switch_character(owner_id, chat_id, second["character_id"])
        self.assertEqual(db.get_active_character_id(owner_id, chat_id), second["character_id"])

        # Leaving as the now-active second alt must still reset the FIRST character too.
        await bot._do_leave_labyrinth(FakeUpdate(owner_id, "", [], chat_id=chat_id))
        self.assertEqual(
            db.get_character_by_id(first["character_id"])["current_location"], "the_colosseum",
            "expected the real character sitting in the Labyrinth to be reset even after the owner switched active alts",
        )
        # Real live ask (2026-09-13): the run itself is now kept alive
        # on leaving an unfinished segment (entry room, no checkpoint
        # reached) -- this test's own real point (character-location
        # reset across an alt switch) is unaffected either way.
        self.assertIsNotNone(db.get_labyrinth_run(chat_id, f"party:{party_id}"))

    async def test_labyrinth_leave_resets_a_benched_or_inactive_member_stuck_at_the_sentinel(self):
        """
        Real live incident (2026-09-04, dev-bridge: Sugar's characters
        "Laurienna"/"Charvenna" -- Fast Travel and the Character Sheet
        both crashed for her, and "look around" replied "You're not in
        the Labyrinth right now" with no way back). Both were found
        stuck at LABYRINTH_LOCATION_SENTINEL with no matching
        labyrinth_runs row, traced to a leave_labyrinth call that
        predates the sentinel-fallback fix directly above this test.
        Manually rescued live via db.update_character_by_id -- this
        test covers the real, still-present GAP that fix left behind:
        _labyrinth_active_party_members's is_benched/is_inactive
        exclusion runs UNCONDITIONALLY, before the sentinel fallback
        the above fix added for the is_active_character case -- so a
        party member who goes benched/inactive while genuinely stuck
        at the sentinel is skipped by that helper entirely, and every
        one of its callers (including leave's own reset loop) never
        sees them. Gameplay call sites (hazard damage, checkpoint
        heals) are RIGHT to keep excluding a benched/inactive member --
        Coffee's own explicit ask (2026-09-03: "the trap ... shouldn't
        definitely be hurting inactive members") -- but leaving the
        Labyrinth must still rescue them, or they're orphaned with no
        way back at all, strictly worse than being swept into a fight
        they're not part of. Fixed in _do_leave_labyrinth itself (not
        _labyrinth_active_party_members, so the gameplay call sites are
        untouched): its own reset loop now also catches any raw party
        member whose current_location genuinely is the sentinel,
        regardless of is_benched/is_inactive.
        """
        owner_id, chat_id = 962038, -962038
        leader = make_basic_character(owner_id, "LeaderTester2", chat_id=chat_id, current_location="the_colosseum")
        db.update_character_by_id(leader["character_id"], defeated_monsters=["colosseum_champion"])
        party_id = db.create_party(owner_id, chat_id)
        db.update_character_by_id(leader["character_id"], party_id=party_id)
        db.switch_character(owner_id, chat_id, leader["character_id"])

        benched_owner_id = 962039
        benched = make_basic_character(benched_owner_id, "BenchedTester2", chat_id=chat_id, current_location="the_colosseum")
        db.update_character_by_id(benched["character_id"], party_id=party_id, is_benched=True)

        await bot._do_enter_labyrinth(FakeUpdate(owner_id, "", [], chat_id=chat_id))
        self.assertEqual(db.get_character_by_id(leader["character_id"])["current_location"], bot.LABYRINTH_LOCATION_SENTINEL)
        # A benched member who was along for the entry is stuck at the sentinel too, same as any real member.
        db.update_character_by_id(benched["character_id"], current_location=bot.LABYRINTH_LOCATION_SENTINEL)

        await bot._do_leave_labyrinth(FakeUpdate(owner_id, "", [], chat_id=chat_id))
        self.assertEqual(
            db.get_character_by_id(benched["character_id"])["current_location"], "the_colosseum",
            "expected a benched member stuck at the sentinel to be rescued on leave, not orphaned",
        )

